const HSK1_DATA = {"lessons": [{"id": 1,"title_cn": "AI小语，你好！","title_pinyin": "AI Xiǎoyǔ, nǐ hǎo!","title_vn": "Chào AI Tiểu Ngữ!","goals": ["Có thể nghe hiểu và sử dụng các cách diễn đạt lịch sự để chào hỏi, cảm ơn và tạm biệt.","Hiểu lễ nghi giao tiếp của người Trung Quốc, có thể nghe hiểu và sử dụng đại từ nhân xưng ngôi thứ hai kính ngữ \"您\"."],"vocab": [{"hanzi": "你好","pinyin": "nǐ hǎo","pos": "","vn": "xin chào"},{"hanzi": "王老师","pinyin": "Wáng lǎoshī","pos": "danh từ riêng","vn": "cô Vương"},{"hanzi": "大家","pinyin": "dàjiā","pos": "đt.","vn": "mọi người"},{"hanzi": "好","pinyin": "hǎo","pos": "tt.","vn": "tốt; khỏe"},{"hanzi": "学生","pinyin": "xuésheng","pos": "dt.","vn": "học sinh"},{"hanzi": "们","pinyin": "men","pos": "htố.","vn": "hậu tố đặt sau đại từ nhân xưng hoặc danh từ để biểu thị số nhiều"},{"hanzi": "老师","pinyin": "lǎoshī","pos": "dt.","vn": "giáo viên, thầy/cô"},{"hanzi": "您","pinyin": "nín","pos": "đt.","vn": "ngài, ông/bà (kính ngữ)"},{"hanzi": "你们","pinyin": "nǐmen","pos": "đt.","vn": "các bạn (số nhiều)"},{"hanzi": "谢谢","pinyin": "xièxie","pos": "dgt.","vn": "cảm ơn"},{"hanzi": "不客气","pinyin": "bú kèqi","pos": "","vn": "không có gì"},{"hanzi": "同学","pinyin": "tóngxué","pos": "dt.","vn": "bạn học"},{"hanzi": "再见","pinyin": "zàijiàn","pos": "dgt.","vn": "tạm biệt"}],"grammar": [],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "王一飞","cn": "AI小语，你好！","pinyin": "AI Xiǎoyǔ, nǐ hǎo!"},{"speaker": "小语","cn": "王老师，你好！","pinyin": "Wáng lǎoshī, nǐ hǎo!"}],"translation_vn": "Vương Nhất Phi: Chào AI Tiểu Ngữ!\nTiểu Ngữ: Chào cô Vương!","audio_dialogue": "1-1.mp3","audio_vocab": "1-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一飞","cn": "大家好！","pinyin": "Dàjiā hǎo!"},{"speaker": "白家月/安妮/陈天中","cn": "老师，您好！","pinyin": "Lǎoshī, nín hǎo!"},{"speaker": "小语","cn": "你们好！","pinyin": "Nǐmen hǎo!"},{"speaker": "白家月/安妮/陈天中","cn": "你好，小语！","pinyin": "Nǐ hǎo, Xiǎoyǔ!"}],"translation_vn": "Vương Nhất Phi: Chào cả lớp!\nBạch Gia Nguyệt/Annie/Trần Thiên Trung: Chào cô ạ!\nTiểu Ngữ: Chào tất cả mọi người!\nBạch Gia Nguyệt/Annie/Trần Thiên Trung: Chào Tiểu Ngữ!","audio_dialogue": "1-3.mp3","audio_vocab": "1-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "白家月/安妮/陈天中","cn": "谢谢！","pinyin": "Xièxie!"},{"speaker": "小语","cn": "不客气！","pinyin": "Bú kèqi!"},{"speaker": "王一飞","cn": "同学们，再见！","pinyin": "Tóngxuémen, zàijiàn!"},{"speaker": "白家月/安妮/陈天中","cn": "老师，再见！","pinyin": "Lǎoshī, zàijiàn!"}],"translation_vn": "Bạch Gia Nguyệt/Annie/Trần Thiên Trung: Cảm ơn cô!\nTiểu Ngữ: Không có gì!\nVương Nhất Phi: Tạm biệt các em!\nBạch Gia Nguyệt/Annie/Trần Thiên Trung: Tạm biệt cô!","audio_dialogue": "1-5.mp3","audio_vocab": "1-6.mp3"}]},{"id": 2,"title_cn": "我叫李文","title_pinyin": "Wǒ jiào Lǐ Wén","title_vn": "Tôi tên là Lý Văn","goals": ["Có thể nghe hiểu và sử dụng tên tiếng Trung để tự giới thiệu bản thân.","Có thể nghe hiểu và sử dụng ngôn ngữ xin lỗi, dùng \"对不起\" để xin lỗi và \"没关系\" để đáp lại.","Nắm được trật tự từ cơ bản trong tiếng Hán.","Hiểu được cấu tạo của tên người Trung Quốc."],"vocab": [{"hanzi": "请问","pinyin": "qǐngwèn","pos": "dgt.","vn": "xin hỏi, làm phiền hỏi"},{"hanzi": "你","pinyin": "nǐ","pos": "đt.","vn": "bạn, anh/chị (số ít)"},{"hanzi": "叫","pinyin": "jiào","pos": "dgt.","vn": "tên là, gọi là"},{"hanzi": "什么","pinyin": "shénme","pos": "đt.","vn": "cái gì, gì"},{"hanzi": "名字","pinyin": "míngzi","pos": "dt.","vn": "tên"},{"hanzi": "我","pinyin": "wǒ","pos": "đt.","vn": "tôi"},{"hanzi": "不","pinyin": "bù","pos": "phó.","vn": "không"},{"hanzi": "是","pinyin": "shì","pos": "dgt.","vn": "là"},{"hanzi": "对不起","pinyin": "duìbuqǐ","pos": "dgt.","vn": "xin lỗi"},{"hanzi": "没关系","pinyin": "méi guānxi","pos": "","vn": "không sao"},{"hanzi": "没事","pinyin": "méishì","pos": "dgt.","vn": "không sao, không có gì"},{"hanzi": "很","pinyin": "hěn","pos": "phó.","vn": "rất"},{"hanzi": "高兴","pinyin": "gāoxìng","pos": "tt.","vn": "vui, vui mừng"},{"hanzi": "认识","pinyin": "rènshi","pos": "dgt.","vn": "quen biết, nhận biết"},{"hanzi": "也","pinyin": "yě","pos": "phó.","vn": "cũng"}],"grammar": [{"title": "汉语的基本语序","explanation_vn": "Trật tự từ cơ bản trong tiếng Hán là: Chủ ngữ + Vị ngữ + Tân ngữ. Ví dụ: 我 (chủ ngữ) 叫 (vị ngữ) 陈天中 (tân ngữ).","examples": [{"cn": "你叫什么名字？","pinyin": "Nǐ jiào shénme míngzi?","vn": "Bạn tên là gì?"},{"cn": "我叫白家月。","pinyin": "Wǒ jiào Bái Jiāyuè.","vn": "Tôi tên là Bạch Gia Nguyệt."},{"cn": "我是学生。","pinyin": "Wǒ shì xuésheng.","vn": "Tôi là học sinh."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "王一飞","cn": "请问，你叫什么名字？","pinyin": "Qǐngwèn, nǐ jiào shénme míngzi?"},{"speaker": "陈天中","cn": "我叫陈天中。","pinyin": "Wǒ jiào Chén Tiānzhōng."}],"translation_vn": "Vương Nhất Phi: Xin hỏi, bạn tên là gì?\nTrần Thiên Trung: Tôi tên là Trần Thiên Trung.","audio_dialogue": "2-1.mp3","audio_vocab": "2-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "陈天中","cn": "你好，安妮！","pinyin": "Nǐ hǎo, Ānnī!"},{"speaker": "白家月","cn": "你好，陈天中！我不是安妮，我是白家月。","pinyin": "Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè."},{"speaker": "陈天中","cn": "对不起！","pinyin": "Duìbuqǐ!"},{"speaker": "白家月","cn": "没关系！","pinyin": "Méi guānxi!"}],"translation_vn": "Trần Thiên Trung: Chào Annie!\nBạch Gia Nguyệt: Chào Trần Thiên Trung! Tôi không phải Annie, tôi là Bạch Gia Nguyệt.\nTrần Thiên Trung: Xin lỗi!\nBạch Gia Nguyệt: Không sao!","audio_dialogue": "2-3.mp3","audio_vocab": "2-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "李文","cn": "你好！我叫李文。","pinyin": "Nǐ hǎo! Wǒ jiào Lǐ Wén."},{"speaker": "白家月","cn": "你好！我叫白家月。","pinyin": "Nǐ hǎo! Wǒ jiào Bái Jiāyuè."},{"speaker": "李文","cn": "很高兴认识你。","pinyin": "Hěn gāoxìng rènshi nǐ."},{"speaker": "白家月","cn": "认识你我也很高兴。","pinyin": "Rènshi nǐ wǒ yě hěn gāoxìng."}],"translation_vn": "Lý Văn: Xin chào! Tôi tên là Lý Văn.\nBạch Gia Nguyệt: Xin chào! Tôi tên là Bạch Gia Nguyệt.\nLý Văn: Rất vui được quen biết bạn.\nBạch Gia Nguyệt: Quen biết bạn tôi cũng rất vui.","audio_dialogue": "2-5.mp3","audio_vocab": "2-6.mp3"}]},{"id": 3,"title_cn": "我是中国人","title_pinyin": "Wǒ shì Zhōngguó rén","title_vn": "Tôi là người Trung Quốc","goals": ["Có thể nghe hiểu và sử dụng câu chữ \"是\" để biểu đạt sự đồng nhất hoặc phân loại.","Nắm được cách dùng trợ từ kết cấu \"的\".","Nắm được cách dùng câu hỏi có/không với \"吗\"."],"vocab": [{"hanzi": "人","pinyin": "rén","pos": "dt.","vn": "người"},{"hanzi": "的","pinyin": "de","pos": "trợ.","vn": "trợ từ kết cấu, biểu thị quan hệ sở hữu/định ngữ"},{"hanzi": "中国","pinyin": "Zhōngguó","pos": "danh từ riêng","vn": "Trung Quốc"},{"hanzi": "法国","pinyin": "Fǎguó","pos": "danh từ riêng","vn": "Pháp"},{"hanzi": "中文","pinyin": "Zhōngwén","pos": "danh từ riêng","vn": "tiếng Trung, Hán ngữ"},{"hanzi": "这","pinyin": "zhè","pos": "đt.","vn": "cái này, đây"},{"hanzi": "谁","pinyin": "shéi/shuí","pos": "đt.","vn": "ai"},{"hanzi": "女朋友","pinyin": "nǚpéngyou","pos": "dt.","vn": "bạn gái"},{"hanzi": "哪","pinyin": "nǎ","pos": "đt.","vn": "nào"},{"hanzi": "国","pinyin": "guó","pos": "dt.","vn": "nước, quốc gia"},{"hanzi": "她","pinyin": "tā","pos": "đt.","vn": "cô ấy, chị ấy"},{"hanzi": "泰国","pinyin": "Tàiguó","pos": "danh từ riêng","vn": "Thái Lan"},{"hanzi": "喂","pinyin": "wèi","pos": "ct.","vn": "này, alô"},{"hanzi": "姐姐","pinyin": "jiějie","pos": "dt.","vn": "chị gái"},{"hanzi": "工作","pinyin": "gōngzuò","pos": "dt.","vn": "công việc"},{"hanzi": "还","pinyin": "hái","pos": "phó.","vn": "vẫn, còn"},{"hanzi": "忙","pinyin": "máng","pos": "tt.","vn": "bận, bận rộn"},{"hanzi": "吗","pinyin": "ma","pos": "trợ.","vn": "trợ từ nghi vấn, đặt cuối câu hỏi có/không"},{"hanzi": "对","pinyin": "duì","pos": "tt.","vn": "đúng"},{"hanzi": "太","pinyin": "tài","pos": "phó.","vn": "quá, rất"},{"hanzi": "我们","pinyin": "wǒmen","pos": "đt.","vn": "chúng tôi, chúng ta"},{"hanzi": "想","pinyin": "xiǎng","pos": "dgt.","vn": "nhớ, mong nhớ"}],"grammar": [{"title": "\"是\"字句","explanation_vn": "Câu chữ \"是\" dùng để biểu thị người hoặc sự vật đồng nhất với cái gì hoặc thuộc loại gì, hình thức phủ định là \"不是\".","examples": [{"cn": "我是法国人。","pinyin": "Wǒ shì Fǎguó rén.","vn": "Tôi là người Pháp."},{"cn": "她是中文老师。","pinyin": "Tā shì Zhōngwén lǎoshī.","vn": "Cô ấy là giáo viên tiếng Trung."},{"cn": "我老师不是法国人。","pinyin": "Wǒ lǎoshī bú shì Fǎguó rén.","vn": "Giáo viên của tôi không phải người Pháp."}]},{"title": "结构助词\"的\"","explanation_vn": "Trợ từ kết cấu \"的\" đặt giữa định ngữ và trung tâm ngữ, biểu đạt quan hệ sở hữu. Nếu trước \"的\" là đại từ nhân xưng, phía sau là từ chỉ quan hệ thân thuộc hoặc danh từ chỉ người, có thể lược bỏ \"的\".","examples": [{"cn": "白家月的中文老师","pinyin": "Bái Jiāyuè de Zhōngwén lǎoshī","vn": "giáo viên tiếng Trung của Bạch Gia Nguyệt"},{"cn": "你的名字","pinyin": "nǐ de míngzi","vn": "tên của bạn"},{"cn": "我老师","pinyin": "wǒ lǎoshī","vn": "giáo viên của tôi"},{"cn": "我学生","pinyin": "wǒ xuésheng","vn": "học sinh của tôi"},{"cn": "你同学","pinyin": "nǐ tóngxué","vn": "bạn học của bạn"},{"cn": "我妈妈","pinyin": "wǒ māma","vn": "mẹ tôi"}]},{"title": "用\"吗\"的是非问句","explanation_vn": "\"吗\" là trợ từ ngữ khí, thường đặt ở cuối câu để biểu thị nghi vấn. Cấu trúc cơ bản: ……吗？","examples": [{"cn": "你也很忙吗？","pinyin": "Nǐ yě hěn máng ma?","vn": "Bạn cũng rất bận à?"},{"cn": "你是他的中文老师吗？","pinyin": "Nǐ shì tā de Zhōngwén lǎoshī ma?","vn": "Bạn là giáo viên tiếng Trung của anh ấy à?"},{"cn": "你有姐姐吗？","pinyin": "Nǐ yǒu jiějie ma?","vn": "Bạn có chị gái không?"}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "李文","cn": "我是中国人。","pinyin": "Wǒ shì Zhōngguó rén."},{"speaker": "白家月","cn": "我是法国人。我的中文老师也是中国人。","pinyin": "Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén."}],"translation_vn": "Lý Văn: Tôi là người Trung Quốc.\nBạch Gia Nguyệt: Tôi là người Pháp. Giáo viên tiếng Trung của tôi cũng là người Trung Quốc.","audio_dialogue": "3-1.mp3","audio_vocab": "3-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "安妮","cn": "这是谁？","pinyin": "Zhè shì shéi?"},{"speaker": "陈天中","cn": "这是我女朋友。","pinyin": "Zhè shì wǒ nǚpéngyou."},{"speaker": "安妮","cn": "你女朋友是哪国人？","pinyin": "Nǐ nǚpéngyou shì nǎ guó rén?"},{"speaker": "陈天中","cn": "她也是泰国人。","pinyin": "Tā yě shì Tàiguó rén."}],"translation_vn": "Annie: Đây là ai vậy?\nTrần Thiên Trung: Đây là bạn gái của tôi.\nAnnie: Bạn gái của bạn là người nước nào?\nTrần Thiên Trung: Cô ấy cũng là người Thái Lan.","audio_dialogue": "3-3.mp3","audio_vocab": "3-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一雪","cn": "喂，一飞！","pinyin": "Wèi, Yīfēi!"},{"speaker": "王一飞","cn": "姐姐！","pinyin": "Jiějie!"},{"speaker": "王一雪","cn": "你工作还忙吗？","pinyin": "Nǐ gōngzuò hái máng ma?"},{"speaker": "王一飞","cn": "对，还很忙。你也很忙吗？","pinyin": "Duì, hái hěn máng. Nǐ yě hěn máng ma?"},{"speaker": "王一雪","cn": "我不太忙。我们很想你。","pinyin": "Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ."},{"speaker": "王一飞","cn": "我也想你们。","pinyin": "Wǒ yě xiǎng nǐmen."}],"translation_vn": "Vương Nhất Tuyết: Alô, Nhất Phi!\nVương Nhất Phi: Chị ơi!\nVương Nhất Tuyết: Công việc của em vẫn bận chứ?\nVương Nhất Phi: Vâng, vẫn bận lắm. Chị cũng bận lắm à?\nVương Nhất Tuyết: Chị không bận lắm. Bọn chị rất nhớ em.\nVương Nhất Phi: Em cũng nhớ mọi người.","audio_dialogue": "3-5.mp3","audio_vocab": "3-6.mp3"}]},{"id": 4,"title_cn": "我有两个孩子","title_pinyin": "Wǒ yǒu liǎng gè háizi","title_vn": "Tôi có hai con","goals": ["Có thể nghe hiểu và sử dụng câu \"有\" (1) để biểu đạt sự sở hữu người hoặc vật.","Nắm vững cách dùng cấu trúc \"A……, B呢？\".","Nắm vững cách dùng số từ, lượng từ được học trong bài này.","Hiểu cách người Trung Quốc hỏi đáp về tuổi tác, có thể sử dụng từ ngữ phù hợp để hỏi đáp về tuổi."],"vocab": [{"hanzi": "有","pinyin": "yǒu","pos": "dgt.","vn": "có"},{"hanzi": "多少","pinyin": "duōshao","pos": "đt.","vn": "bao nhiêu"},{"hanzi": "个","pinyin": "gè","pos": "lượng.","vn": "cái (lượng từ chung)"},{"hanzi": "哥哥","pinyin": "gēge","pos": "dt.","vn": "anh trai"},{"hanzi": "呢","pinyin": "ne","pos": "trợ.","vn": "trợ từ ngữ khí dùng ở cuối câu nghi vấn"},{"hanzi": "没有","pinyin": "méiyǒu","pos": "dgt.","vn": "không có"},{"hanzi": "家","pinyin": "jiā","pos": "dt.","vn": "nhà, gia đình"},{"hanzi": "几","pinyin": "jǐ","pos": "đt.","vn": "mấy"},{"hanzi": "口","pinyin": "kǒu","pos": "lượng.","vn": "lượng từ dùng để đếm người trong gia đình, dao, v.v."},{"hanzi": "爸爸","pinyin": "bàba","pos": "dt.","vn": "bố"},{"hanzi": "妈妈","pinyin": "māma","pos": "dt.","vn": "mẹ"},{"hanzi": "妹妹","pinyin": "mèimei","pos": "dt.","vn": "em gái"},{"hanzi": "和","pinyin": "hé","pos": "liên.","vn": "và"},{"hanzi": "儿子","pinyin": "érzi","pos": "dt.","vn": "con trai"},{"hanzi": "孩子","pinyin": "háizi","pos": "dt.","vn": "con, con cái"},{"hanzi": "女儿","pinyin": "nǚ'ér","pos": "dt.","vn": "con gái"},{"hanzi": "岁","pinyin": "suì","pos": "lượng.","vn": "tuổi"},{"hanzi": "他","pinyin": "tā","pos": "đt.","vn": "anh ấy, nó, cậu ấy"},{"hanzi": "今年","pinyin": "jīnnián","pos": "dt.","vn": "năm nay"},{"hanzi": "多","pinyin": "duō","pos": "đt.","vn": "bao nhiêu, đến mức nào (dùng hỏi về mức độ)"},{"hanzi": "大","pinyin": "dà","pos": "tt.","vn": "(tuổi) lớn, nhiều"}],"grammar": [{"title": "\"有\"字句（1） \"Có\" Sentence (1)","explanation_vn": "\"有\" trong bài này biểu thị sự sở hữu, hình thức phủ định là \"没/没有\".","examples": [{"cn": "她有二十个学生。","pinyin": "Tā yǒu èrshí gè xuésheng.","vn": "Cô ấy có hai mươi học sinh."},{"cn": "她有一个姐姐。","pinyin": "Tā yǒu yí gè jiějie.","vn": "Cô ấy có một chị gái."},{"cn": "我没/没有姐姐。","pinyin": "Wǒ méi/méiyǒu jiějie.","vn": "Tôi không có chị gái."}]},{"title": "数字的表达 Expression of Numbers","explanation_vn": "Trong tiếng Hán, số có hai cách viết: chữ số Ả Rập và chữ Hán, ví dụ \"1\" và \"一\". Với số \"2\", khi dùng làm số thứ tự (như \"第二\") thì đọc là \"二 (èr)\", còn khi đứng trước lượng từ thì đọc là \"两 (liǎng)\".","examples": [{"cn": "十二","pinyin": "shí'èr","vn": "12"},{"cn": "二十二","pinyin": "èrshí'èr","vn": "22"},{"cn": "一百二十二","pinyin": "yìbǎi èrshí'èr","vn": "122"},{"cn": "两个人","pinyin": "liǎng gè rén","vn": "hai người"},{"cn": "两口人","pinyin": "liǎng kǒu rén","vn": "hai người (trong gia đình)"},{"cn": "两本书","pinyin": "liǎng běn shū","vn": "hai quyển sách"}]},{"title": "语气助词\"呢\"（1） Modal Particle \"呢\" (1)","explanation_vn": "\"呢\" trong bài này đặt ở cuối câu, biểu thị nghi vấn, hỏi về tình huống đã được nhắc đến ở trên. Cấu trúc cơ bản: A……, B呢？","examples": [{"cn": "我有两个哥哥，你呢？","pinyin": "Wǒ yǒu liǎng gè gēge, nǐ ne?","vn": "Tôi có hai anh trai, còn bạn thì sao?"},{"cn": "我叫白家月，你呢？","pinyin": "Wǒ jiào Bái Jiāyuè, nǐ ne?","vn": "Tôi tên là Bạch Gia Nguyệt, còn bạn?"},{"cn": "我是中国人，你呢？","pinyin": "Wǒ shì Zhōngguó rén, nǐ ne?","vn": "Tôi là người Trung Quốc, còn bạn?"}]},{"title": "名量词和名量结构 Nominal Measure Words and [Num+M+(N)] Structure","explanation_vn": "Khi biểu đạt số lượng, số từ trong tiếng Hán thường phải đi kèm với lượng từ. Bài này học các danh lượng từ chỉ số lượng người hoặc vật như \"口, 个\", cùng với cấu trúc [Số từ + Lượng từ + (Danh từ)] như \"四口人, 两个哥哥\".","examples": [{"cn": "四口","pinyin": "sì kǒu","vn": "bốn người (trong gia đình)"},{"cn": "四口人","pinyin": "sì kǒu rén","vn": "bốn người trong gia đình"},{"cn": "两个","pinyin": "liǎng gè","vn": "hai (cái/người)"},{"cn": "两个学生","pinyin": "liǎng gè xuésheng","vn": "hai học sinh"}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "刘明","cn": "一飞忙吗？","pinyin": "Yīfēi máng ma?"},{"speaker": "王一雪","cn": "她很忙。","pinyin": "Tā hěn máng."},{"speaker": "刘明","cn": "她有多少个学生？","pinyin": "Tā yǒu duōshao gè xuésheng?"},{"speaker": "王一雪","cn": "她有二十个学生。","pinyin": "Tā yǒu èrshí gè xuésheng."}],"translation_vn": "Lưu Minh: Nhất Phi có bận không?\nVương Nhất Tuyết: Chị ấy rất bận.\nLưu Minh: Chị ấy có bao nhiêu học sinh?\nVương Nhất Tuyết: Chị ấy có hai mươi học sinh.","audio_dialogue": "4-1.mp3","audio_vocab": "4-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一雪","cn": "我有两个哥哥，你呢？","pinyin": "Wǒ yǒu liǎng gè gēge, nǐ ne?"},{"speaker": "杨同乐","cn": "我没有哥哥。","pinyin": "Wǒ méiyǒu gēge."},{"speaker": "王一雪","cn": "你家有几口人？","pinyin": "Nǐ jiā yǒu jǐ kǒu rén?"},{"speaker": "杨同乐","cn": "我家有四口人，爸爸、妈妈、妹妹和我。","pinyin": "Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ."}],"translation_vn": "Vương Nhất Tuyết: Tôi có hai anh trai, còn bạn?\nDương Đồng Lạc: Tôi không có anh trai.\nVương Nhất Tuyết: Nhà bạn có mấy người?\nDương Đồng Lạc: Nhà tôi có bốn người: bố, mẹ, em gái và tôi.","audio_dialogue": "4-3.mp3","audio_vocab": "4-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "杨同乐","cn": "这是您儿子吗？","pinyin": "Zhè shì nín érzi ma?"},{"speaker": "王一雪","cn": "是的。我有两个孩子，一个儿子，一个女儿。","pinyin": "Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér."},{"speaker": "杨同乐","cn": "您儿子几岁？","pinyin": "Nín érzi jǐ suì?"},{"speaker": "王一雪","cn": "他今年五岁。","pinyin": "Tā jīnnián wǔ suì."},{"speaker": "杨同乐","cn": "您女儿多大？","pinyin": "Nín nǚ'ér duō dà?"},{"speaker": "王一雪","cn": "她今年十二。","pinyin": "Tā jīnnián shí'èr."}],"translation_vn": "Dương Đồng Lạc: Đây là con trai của chị ạ?\nVương Nhất Tuyết: Đúng vậy. Tôi có hai con, một con trai, một con gái.\nDương Đồng Lạc: Con trai chị mấy tuổi rồi?\nVương Nhất Tuyết: Cháu năm nay năm tuổi.\nDương Đồng Lạc: Con gái chị bao nhiêu tuổi rồi?\nVương Nhất Tuyết: Cháu năm nay mười hai tuổi.","audio_dialogue": "4-5.mp3","audio_vocab": "4-6.mp3"}]},{"id": 5,"title_cn": "今天我休息","title_pinyin": "Jīntiān wǒ xiūxi","title_vn": "Hôm nay tôi nghỉ","goals": ["Có thể nghe hiểu, đọc hiểu và miêu tả ngày tháng xảy ra sự việc, hành vi theo thói quen của tiếng Trung.","Có thể nghe hiểu và sử dụng động từ năng nguyện \"会\" để biểu đạt việc biết làm hoặc có khả năng làm việc gì đó.","Nắm vững cách dùng câu có vị ngữ là danh từ."],"vocab": [{"hanzi": "今天","pinyin": "jīntiān","pos": "dt.","vn": "hôm nay"},{"hanzi": "号","pinyin": "hào","pos": "lượng.","vn": "ngày (trong tháng)"},{"hanzi": "月","pinyin": "yuè","pos": "dt.","vn": "tháng"},{"hanzi": "日","pinyin": "rì","pos": "lượng.","vn": "ngày"},{"hanzi": "星期","pinyin": "xīngqī","pos": "dt.","vn": "tuần"},{"hanzi": "星期日","pinyin": "Xīngqīrì","pos": "dt.","vn": "Chủ nhật"},{"hanzi": "星期天","pinyin": "Xīngqītiān","pos": "dt.","vn": "Chủ nhật"},{"hanzi": "休息","pinyin": "xiūxi","pos": "dgt.","vn": "nghỉ ngơi"},{"hanzi": "会","pinyin": "huì","pos": "đtnn.","vn": "biết, có thể"},{"hanzi": "做饭","pinyin": "zuò fàn","pos": "","vn": "nấu cơm, nấu ăn"},{"hanzi": "做","pinyin": "zuò","pos": "dgt.","vn": "làm, chế biến"},{"hanzi": "面条儿","pinyin": "miàntiáor","pos": "dt.","vn": "mì sợi"},{"hanzi": "饺子","pinyin": "jiǎozi","pos": "dt.","vn": "sủi cảo (jiaozi)"},{"hanzi": "一些","pinyin": "yìxiē","pos": "sl.","vn": "một ít, một vài"},{"hanzi": "菜","pinyin": "cài","pos": "dt.","vn": "món ăn"},{"hanzi": "下班","pinyin": "xiàbān","pos": "dgt.","vn": "tan làm, hết giờ làm"},{"hanzi": "新","pinyin": "xīn","pos": "tt.","vn": "mới"},{"hanzi": "电脑","pinyin": "diànnǎo","pos": "dt.","vn": "máy tính"},{"hanzi": "真","pinyin": "zhēn","pos": "phó.","vn": "thật, thật sự"},{"hanzi": "好看","pinyin": "hǎokàn","pos": "tt.","vn": "đẹp, đẹp mắt"},{"hanzi": "喜欢","pinyin": "xǐhuan","pos": "dgt.","vn": "thích"},{"hanzi": "它","pinyin": "tā","pos": "đt.","vn": "nó"}],"grammar": [{"title": "时间的表达（1） Expression of Time (1)","explanation_vn": "Bài này học cách biểu đạt ngày tháng và thứ trong tuần. Thứ tự biểu đạt ngày tháng, thứ trong tiếng Hán là: năm → tháng → ngày/số → thứ.","examples": [{"cn": "1992年5月16日/号，星期六","pinyin": "yī jiǔ jiǔ èr nián wǔ yuè shíliù rì/hào, Xīngqīliù","vn": "Thứ Bảy, ngày 16 tháng 5 năm 1992"},{"cn": "2024年10月22日/号，星期二","pinyin": "èr líng èr sì nián shí yuè èrshí'èr rì/hào, Xīngqī'èr","vn": "Thứ Ba, ngày 22 tháng 10 năm 2024"},{"cn": "今天9月8号。","pinyin": "Jīntiān jiǔ yuè bā hào.","vn": "Hôm nay là ngày 8 tháng 9."},{"cn": "今天是2025年5月22号。","pinyin": "Jīntiān shì èr líng èr wǔ nián wǔ yuè èrshí'èr hào.","vn": "Hôm nay là ngày 22 tháng 5 năm 2025."},{"cn": "明天是2024年8月18号，星期天。","pinyin": "Míngtiān shì èr líng èr sì nián bā yuè shíbā hào, Xīngqītiān.","vn": "Ngày mai là Chủ nhật, ngày 18 tháng 8 năm 2024."}]},{"title": "名词谓语句 Nominal-Predicate Sentences","explanation_vn": "Trong câu có vị ngữ là danh từ, phần vị ngữ chỉ gồm danh từ hoặc thành phần mang tính danh từ, các từ ngữ này thường biểu thị thời gian, ngày tháng, tuổi tác, v.v.","examples": [{"cn": "今天几号？今天5月1号。","pinyin": "Jīntiān jǐ hào? Jīntiān wǔ yuè yī hào.","vn": "Hôm nay là ngày mấy? Hôm nay là ngày 1 tháng 5."},{"cn": "我妹妹12岁。","pinyin": "Wǒ mèimei shí'èr suì.","vn": "Em gái tôi 12 tuổi."}]},{"title": "能愿动词\"会\" Modal Verb \"会\"","explanation_vn": "\"会\" đặt trước động từ, biểu thị việc thông qua học tập mà biết cách làm hoặc có khả năng làm việc gì đó.","examples": [{"cn": "你会做饭吗？","pinyin": "Nǐ huì zuò fàn ma?","vn": "Bạn có biết nấu ăn không?"},{"cn": "我会做面条儿。","pinyin": "Wǒ huì zuò miàntiáor.","vn": "Tôi biết làm mì."},{"cn": "我不会做菜。","pinyin": "Wǒ bú huì zuò cài.","vn": "Tôi không biết nấu món ăn."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "王一雪","cn": "今天几号？","pinyin": "Jīntiān jǐ hào?"},{"speaker": "刘明","cn": "今天9月8号。","pinyin": "Jīntiān jiǔ yuè bā hào."},{"speaker": "王一雪","cn": "星期几？","pinyin": "Xīngqī jǐ?"},{"speaker": "刘明","cn": "星期日。今天我休息。","pinyin": "Xīngqīrì. Jīntiān wǒ xiūxi."}],"translation_vn": "Vương Nhất Tuyết: Hôm nay là ngày mấy?\nLưu Minh: Hôm nay là ngày 8 tháng 9.\nVương Nhất Tuyết: Thứ mấy?\nLưu Minh: Chủ nhật. Hôm nay tôi nghỉ.","audio_dialogue": "5-1.mp3","audio_vocab": "5-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一雪","cn": "你会做饭吗？","pinyin": "Nǐ huì zuò fàn ma?"},{"speaker": "杨同乐","cn": "我会做。","pinyin": "Wǒ huì zuò."},{"speaker": "王一雪","cn": "你会做什么？","pinyin": "Nǐ huì zuò shénme?"},{"speaker": "杨同乐","cn": "我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","pinyin": "Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn."}],"translation_vn": "Vương Nhất Tuyết: Bạn có biết nấu ăn không?\nDương Đồng Lạc: Tôi biết nấu.\nVương Nhất Tuyết: Bạn biết làm món gì?\nDương Đồng Lạc: Tôi biết làm mì, sủi cảo, cũng biết nấu một vài món ăn. Chủ nhật tôi cũng nấu cơm.","audio_dialogue": "5-3.mp3","audio_vocab": "5-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一雪","cn": "同乐，下班吗？","pinyin": "Tóngle, xiàbān ma?"},{"speaker": "杨同乐","cn": "下班。","pinyin": "Xiàbān."},{"speaker": "王一雪","cn": "这是你的新电脑吗？","pinyin": "Zhè shì nǐ de xīn diànnǎo ma?"},{"speaker": "杨同乐","cn": "是的，是我的新电脑。","pinyin": "Shì de, shì wǒ de xīn diànnǎo."},{"speaker": "王一雪","cn": "真好看！","pinyin": "Zhēn hǎokàn!"},{"speaker": "杨同乐","cn": "我也很喜欢它。","pinyin": "Wǒ yě hěn xǐhuan tā."}],"translation_vn": "Vương Nhất Tuyết: Đồng Lạc, tan làm rồi à?\nDương Đồng Lạc: Tan làm rồi.\nVương Nhất Tuyết: Đây là máy tính mới của bạn à?\nDương Đồng Lạc: Đúng vậy, là máy tính mới của tôi.\nVương Nhất Tuyết: Đẹp thật đấy!\nDương Đồng Lạc: Tôi cũng rất thích nó.","audio_dialogue": "5-5.mp3","audio_vocab": "5-6.mp3"}]},{"id": 6,"title_cn": "你的手机号是多少？","title_pinyin": "Nǐ de shǒujīhào shì duōshao?","title_vn": "Số điện thoại di động của bạn là bao nhiêu?","goals": ["Có thể nghe hiểu số điện thoại di động và sử dụng số để gọi điện.","Có thể nghe hiểu và sử dụng hai hoặc nhiều cụm động từ để biểu đạt mục đích hoặc cách thức của hành động.","Nắm vững cách dùng động từ năng nguyện \"想\".","Nắm vững cách dùng đại từ nghi vấn \"怎么\" để hỏi về cách thức."],"vocab": [{"hanzi": "手机","pinyin": "shǒujī","pos": "dt.","vn": "điện thoại di động"},{"hanzi": "电话","pinyin": "diànhuà","pos": "dt.","vn": "điện thoại, cuộc gọi"},{"hanzi": "号","pinyin": "hào","pos": "dt.","vn": "số"},{"hanzi": "明天","pinyin": "míngtiān","pos": "dt.","vn": "ngày mai"},{"hanzi": "去","pinyin": "qù","pos": "dgt.","vn": "đi"},{"hanzi": "哪儿","pinyin": "nǎr","pos": "đt.","vn": "đâu, chỗ nào"},{"hanzi": "想","pinyin": "xiǎng","pos": "đtnn.","vn": "muốn"},{"hanzi": "超市","pinyin": "chāoshì","pos": "dt.","vn": "siêu thị"},{"hanzi": "买","pinyin": "mǎi","pos": "dgt.","vn": "mua"},{"hanzi": "东西","pinyin": "dōngxi","pos": "dt.","vn": "đồ, thứ"},{"hanzi": "些","pinyin": "xiē","pos": "lượng.","vn": "vài, một số"},{"hanzi": "牛奶","pinyin": "niúnǎi","pos": "dt.","vn": "sữa (bò)"},{"hanzi": "吃","pinyin": "chī","pos": "dgt.","vn": "ăn"},{"hanzi": "晚饭","pinyin": "wǎnfàn","pos": "dt.","vn": "bữa tối, cơm tối"},{"hanzi": "那边","pinyin": "nàbiān","pos": "đt.","vn": "đằng kia, chỗ đó"},{"hanzi": "包子","pinyin": "bāozi","pos": "dt.","vn": "bánh bao"},{"hanzi": "非常","pinyin": "fēicháng","pos": "phó.","vn": "rất, vô cùng"},{"hanzi": "好吃","pinyin": "hǎochī","pos": "tt.","vn": "ngon"},{"hanzi": "米饭","pinyin": "mǐfàn","pos": "dt.","vn": "cơm"},{"hanzi": "怎么","pinyin": "zěnme","pos": "đt.","vn": "như thế nào, làm sao, bằng cách nào"},{"hanzi": "坐","pinyin": "zuò","pos": "dgt.","vn": "đi (bằng phương tiện), ngồi"},{"hanzi": "出租车","pinyin": "chūzūchē","pos": "dt.","vn": "xe taxi"},{"hanzi": "西安饭店","pinyin": "Xī'ān Fàndiàn","pos": "danh từ riêng","vn": "Nhà hàng Tây An"}],"grammar": [{"title": "能愿动词\"想\" Modal Verb \"想\"","explanation_vn": "Động từ năng nguyện \"想\" đặt trước động từ, biểu thị mong muốn, dự định.","examples": [{"cn": "我想去超市。","pinyin": "Wǒ xiǎng qù chāoshì.","vn": "Tôi muốn đi siêu thị."},{"cn": "我哥哥不想休息。","pinyin": "Wǒ gēge bù xiǎng xiūxi.","vn": "Anh trai tôi không muốn nghỉ ngơi."}]},{"title": "连动句（1） Serial Verb Sentences (1)","explanation_vn": "Vị ngữ của câu liên động do hai hoặc nhiều cụm động từ cấu thành. Câu liên động thường biểu thị hai ý nghĩa: (1) biểu thị mục đích của hành động; (2) biểu thị cách thức của hành động.","examples": [{"cn": "我想去超市买东西。","pinyin": "Wǒ xiǎng qù chāoshì mǎi dōngxi.","vn": "Tôi muốn đi siêu thị mua đồ."},{"cn": "我们去西安饭店吃晚饭。","pinyin": "Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn.","vn": "Chúng tôi đi Nhà hàng Tây An ăn tối."},{"cn": "我们坐出租车去西安饭店。","pinyin": "Wǒmen zuò chūzūchē qù Xī'ān Fàndiàn.","vn": "Chúng tôi đi taxi đến Nhà hàng Tây An."},{"cn": "她坐出租车去超市。","pinyin": "Tā zuò chūzūchē qù chāoshì.","vn": "Cô ấy đi taxi đến siêu thị."}]},{"title": "疑问代词\"怎么\" Interrogative Pronoun \"怎么\"","explanation_vn": "Đại từ nghi vấn \"怎么\" đặt trước động từ, dùng để hỏi về cách thức.","examples": [{"cn": "我们怎么去？","pinyin": "Wǒmen zěnme qù?","vn": "Chúng ta đi bằng cách nào?"},{"cn": "她怎么去超市？","pinyin": "Tā zěnme qù chāoshì?","vn": "Cô ấy đi siêu thị bằng cách nào?"}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "李文","cn": "家月，你的手机号是多少？","pinyin": "Jiāyuè, nǐ de shǒujīhào shì duōshao?"},{"speaker": "白家月","cn": "我的手机号是+33 601493190。","pinyin": "Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng."},{"speaker": "李文","cn": "我的手机号是+86 13552721160。","pinyin": "Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng."},{"speaker": "白家月","cn": "好的。","pinyin": "Hǎo de."}],"translation_vn": "Lý Văn: Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?\nBạch Gia Nguyệt: Số điện thoại di động của tôi là +33 601493190.\nLý Văn: Số điện thoại di động của tôi là +86 13552721160.\nBạch Gia Nguyệt: Được rồi.","audio_dialogue": "6-1.mp3","audio_vocab": "6-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "陈天中","cn": "家月，明天你去哪儿？","pinyin": "Jiāyuè, míngtiān nǐ qù nǎr?"},{"speaker": "白家月","cn": "我想去超市买东西。","pinyin": "Wǒ xiǎng qù chāoshì mǎi dōngxi."},{"speaker": "陈天中","cn": "你去超市买什么？","pinyin": "Nǐ qù chāoshì mǎi shénme?"},{"speaker": "白家月","cn": "我想买些牛奶。","pinyin": "Wǒ xiǎng mǎi xiē niúnǎi."}],"translation_vn": "Trần Thiên Trung: Gia Nguyệt, ngày mai bạn đi đâu?\nBạch Gia Nguyệt: Tôi muốn đi siêu thị mua đồ.\nTrần Thiên Trung: Bạn đi siêu thị mua gì?\nBạch Gia Nguyệt: Tôi muốn mua một ít sữa.","audio_dialogue": "6-3.mp3","audio_vocab": "6-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一雪","cn": "星期天我们去哪儿吃晚饭？","pinyin": "Xīngqītiān wǒmen qù nǎr chī wǎnfàn?"},{"speaker": "刘明","cn": "我还想去西安饭店。","pinyin": "Wǒ hái xiǎng qù Xī'ān Fàndiàn."},{"speaker": "刘小雪","cn": "那边的包子非常好吃，我想吃包子。","pinyin": "Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi."},{"speaker": "刘小明","cn": "妈妈，我想吃米饭，不想吃包子。","pinyin": "Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi."},{"speaker": "王一雪","cn": "好的。我们怎么去？","pinyin": "Hǎo de. Wǒmen zěnme qù?"},{"speaker": "刘明","cn": "坐出租车去。","pinyin": "Zuò chūzūchē qù."}],"translation_vn": "Vương Nhất Tuyết: Chủ nhật chúng ta đi đâu ăn tối?\nLưu Minh: Anh vẫn muốn đi Nhà hàng Tây An.\nLưu Tiểu Tuyết: Bánh bao ở đó rất ngon, con muốn ăn bánh bao.\nLưu Tiểu Minh: Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao.\nVương Nhất Tuyết: Được rồi. Chúng ta đi bằng gì?\nLưu Minh: Đi taxi.","audio_dialogue": "6-5.mp3","audio_vocab": "6-6.mp3"}]},{"id": 7,"title_cn": "我晚上六点半下班","title_pinyin": "Wǒ wǎnshang liù diǎn bàn xiàbān","title_vn": "Tôi tan làm lúc sáu giờ rưỡi tối","goals": ["Có thể nghe hiểu và miêu tả thời gian xảy ra sự việc.","Nắm vững cách dùng trợ từ ngữ khí \"吧\" (1) để diễn đạt đề nghị, bàn bạc, v.v.","Nắm vững cách dùng trợ từ ngữ khí \"呢\" (2) để diễn đạt sự việc đã được xác nhận.","Nắm vững vị trí của phó từ, từ ngữ chỉ thời gian khi làm trạng ngữ."],"vocab": [{"hanzi": "现在","pinyin": "xiànzài","pos": "dt.","vn": "hiện nay, bây giờ"},{"hanzi": "点","pinyin": "diǎn","pos": "lượng.","vn": "giờ"},{"hanzi": "早上","pinyin": "zǎoshang","pos": "dt.","vn": "buổi sáng sớm"},{"hanzi": "上午","pinyin": "shàngwǔ","pos": "dt.","vn": "buổi sáng"},{"hanzi": "分","pinyin": "fēn","pos": "lượng.","vn": "phút"},{"hanzi": "课","pinyin": "kè","pos": "dt.","vn": "tiết học; bài học"},{"hanzi": "下午","pinyin": "xiàwǔ","pos": "dt.","vn": "buổi chiều"},{"hanzi": "见","pinyin": "jiàn","pos": "dgt.","vn": "gặp"},{"hanzi": "吧","pinyin": "ba","pos": "trợ.","vn": "trợ từ ngữ khí biểu thị đề nghị, bàn bạc, khuyên bảo, yêu cầu"},{"hanzi": "电影院","pinyin": "diànyǐngyuàn","pos": "dt.","vn": "rạp chiếu phim"},{"hanzi": "看","pinyin": "kàn","pos": "dgt.","vn": "xem; nhìn; đọc"},{"hanzi": "电影","pinyin": "diànyǐng","pos": "dt.","vn": "phim"},{"hanzi": "事","pinyin": "shì","pos": "dt.","vn": "việc, chuyện"},{"hanzi": "上课","pinyin": "shàngkè","pos": "dgt.","vn": "lên lớp, học"},{"hanzi": "呢","pinyin": "ne","pos": "trợ.","vn": "trợ từ ngữ khí xác nhận sự việc"},{"hanzi": "半","pinyin": "bàn","pos": "số.","vn": "rưỡi, nửa"},{"hanzi": "下课","pinyin": "xiàkè","pos": "dgt.","vn": "tan học, hết tiết"},{"hanzi": "在","pinyin": "zài","pos": "dgt.","vn": "ở, tại"},{"hanzi": "家","pinyin": "jiā","pos": "dt.","vn": "nhà"},{"hanzi": "里","pinyin": "lǐ","pos": "dt.","vn": "bên trong, trong"},{"hanzi": "晚上","pinyin": "wǎnshang","pos": "dt.","vn": "buổi tối"},{"hanzi": "医院","pinyin": "yīyuàn","pos": "dt.","vn": "bệnh viện"},{"hanzi": "上班","pinyin": "shàngbān","pos": "dgt.","vn": "đi làm"},{"hanzi": "店","pinyin": "diàn","pos": "dt.","vn": "cửa hàng"},{"hanzi": "菜","pinyin": "cài","pos": "dt.","vn": "rau; món ăn"},{"hanzi": "分钟","pinyin": "fēnzhōng","pos": "lượng.","vn": "phút"},{"hanzi": "后","pinyin": "hòu","pos": "dt.","vn": "sau, sau đó"}],"grammar": [{"title": "时间的表达（2）","explanation_vn": "Dùng \"点\" và \"分\" để diễn đạt mốc thời gian cụ thể: \"点\" dùng cho giờ chẵn, không phải giờ chẵn thì dùng \"分\" (phút); \"分\" có thể lược bỏ, nhưng khi là \"mười phút\" thì không được lược bỏ \"分\"; khi thời gian dưới mười phút phải đọc \"零\". Ngoài ra, các danh từ chỉ thời gian như \"上午, 中午, 下午, 晚上\" có thể dùng để diễn đạt khoảng thời gian, và có thể đứng trước mốc thời gian cụ thể.","examples": [{"cn": "现在二十一点十分。","pinyin": "Xiànzài èrshíyī diǎn shí fēn.","vn": "Bây giờ là 21 giờ 10 phút."},{"cn": "下午两点半。","pinyin": "Xiàwǔ liǎng diǎn bàn.","vn": "Hai giờ rưỡi chiều."},{"cn": "晚上九点十分。","pinyin": "Wǎnshang jiǔ diǎn shí fēn.","vn": "Chín giờ mười phút tối."}]},{"title": "语气助词“吧”(1)","explanation_vn": "Trong bài này, trợ từ ngữ khí \"吧\" đọc nhẹ (ba), đặt ở cuối câu, biểu thị sự đề nghị, bàn bạc, khuyên bảo hoặc yêu cầu.","examples": [{"cn": "我们下午三点见吧。","pinyin": "Wǒmen xiàwǔ sān diǎn jiàn ba.","vn": "Chúng ta gặp nhau lúc ba giờ chiều nhé."},{"cn": "你去超市买吧。","pinyin": "Nǐ qù chāoshì mǎi ba.","vn": "Bạn đi siêu thị mua đi."},{"cn": "我们去西安饭店吃晚饭吧。","pinyin": "Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn ba.","vn": "Chúng ta đi nhà hàng Tây An ăn tối nhé."}]},{"title": "副词、时间词语作状语的位置","explanation_vn": "Trong tiếng Hán, khi phó từ, từ ngữ chỉ thời gian làm trạng ngữ, thường phải đặt trước động từ hoặc tính từ.","examples": [{"cn": "我不想去。","pinyin": "Wǒ bù xiǎng qù.","vn": "Tôi không muốn đi."},{"cn": "妹妹很高兴。","pinyin": "Mèimei hěn gāoxìng.","vn": "Em gái rất vui."},{"cn": "她上午十点半上课。","pinyin": "Tā shàngwǔ shí diǎn bàn shàngkè.","vn": "Cô ấy mười giờ rưỡi sáng lên lớp."}]},{"title": "语气助词“呢”(2)","explanation_vn": "Trợ từ ngữ khí \"呢\" trong bài này đặt ở cuối câu, biểu thị sự xác nhận một sự việc. Cấu trúc cơ bản: ……呢。","examples": [{"cn": "我明天下午两点还上课呢。","pinyin": "Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.","vn": "Ngày mai lúc hai giờ chiều tôi vẫn còn phải học đấy."},{"cn": "妹妹会做两个菜呢。","pinyin": "Mèimei huì zuò liǎng gè cài ne.","vn": "Em gái biết nấu hai món ăn đấy."},{"cn": "李文晚上还有事呢。","pinyin": "Lǐ Wén wǎnshang hái yǒu shì ne.","vn": "Lý Văn tối nay vẫn còn việc đấy."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "白家月","cn": "现在几点？","pinyin": "Xiànzài jǐ diǎn?"},{"speaker": "安妮","cn": "早上八点四十。","pinyin": "Zǎoshang bā diǎn sìshí."},{"speaker": "白家月","cn": "我上午十点十分有课。","pinyin": "Wǒ shàngwǔ shí diǎn shí fēn yǒu kè."},{"speaker": "安妮","cn": "好的，我们下午两点见吧。","pinyin": "Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba."}],"translation_vn": "Bạch Gia Nguyệt: Bây giờ là mấy giờ?\nAnnie: Tám giờ bốn mươi sáng.\nBạch Gia Nguyệt: Tôi có tiết học lúc mười giờ mười phút sáng.\nAnnie: Được, chiều chúng ta gặp nhau lúc hai giờ nhé.","audio_dialogue": "7-1.mp3","audio_vocab": "7-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "李文","cn": "下午我想去电影院看电影，你去吗？","pinyin": "Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?"},{"speaker": "白家月","cn": "我不想去，下午还有事。","pinyin": "Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì."},{"speaker": "李文","cn": "好的。明天呢？","pinyin": "Hǎo de. Míngtiān ne?"},{"speaker": "白家月","cn": "我明天下午两点还上课呢，四点半下课。","pinyin": "Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè."}],"translation_vn": "Lý Văn: Chiều nay tôi muốn đi rạp xem phim, bạn đi không?\nBạch Gia Nguyệt: Tôi không muốn đi, chiều nay tôi còn có việc.\nLý Văn: Được rồi. Thế ngày mai thì sao?\nBạch Gia Nguyệt: Ngày mai chiều tôi vẫn còn phải học đến hai giờ, bốn giờ rưỡi mới tan học.","audio_dialogue": "7-3.mp3","audio_vocab": "7-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一雪","cn": "喂，你在哪儿呢？","pinyin": "Wèi, nǐ zài nǎr ne?"},{"speaker": "刘明","cn": "我在家里呢。","pinyin": "Wǒ zài jiā li ne."},{"speaker": "王一雪","cn": "我晚上六点半下班。","pinyin": "Wǒ wǎnshang liù diǎn bàn xiàbān."},{"speaker": "刘明","cn": "我八点去医院上班。","pinyin": "Wǒ bā diǎn qù yīyuàn shàngbān."},{"speaker": "王一雪","cn": "好的，你去店里买些菜吧。","pinyin": "Hǎo de, nǐ qù diàn li mǎi xiē cài ba."},{"speaker": "刘明","cn": "好，我十分钟后去。","pinyin": "Hǎo, wǒ shí fēnzhōng hòu qù."}],"translation_vn": "Vương Nhất Tuyết: Alo, anh đang ở đâu thế?\nLưu Minh: Anh đang ở nhà.\nVương Nhất Tuyết: Tối nay em tan làm lúc sáu giờ rưỡi.\nLưu Minh: Anh đi làm ở bệnh viện lúc tám giờ.\nVương Nhất Tuyết: Được rồi, anh ghé cửa hàng mua ít rau nhé.\nLưu Minh: Được, mười phút nữa anh đi.","audio_dialogue": "7-5.mp3","audio_vocab": "7-6.mp3"}]},{"id": 8,"title_cn": "我爸爸也在医院工作","title_pinyin": "Wǒ bàba yě zài yīyuàn gōngzuò","title_vn": "Bố tôi cũng làm việc ở bệnh viện","goals": ["Có thể nghe hiểu và miêu tả thông tin về nơi chốn, vị trí.","Nắm vững cách dùng giới từ \"在\" để biểu thị phương vị.","Nắm vững cách dùng động từ năng nguyện \"能\"."],"vocab": [{"hanzi": "房间","pinyin": "fángjiān","pos": "dt.","vn": "phòng"},{"hanzi": "外","pinyin": "wài","pos": "dt.","vn": "ngoài, bên ngoài"},{"hanzi": "只","pinyin": "zhī","pos": "lượng.","vn": "con (lượng từ chỉ động vật)"},{"hanzi": "小","pinyin": "xiǎo","pos": "tt.","vn": "nhỏ, bé"},{"hanzi": "猫","pinyin": "māo","pos": "dt.","vn": "mèo"},{"hanzi": "没","pinyin": "méi","pos": "phó.","vn": "không, chưa"},{"hanzi": "看见","pinyin": "kànjiàn","pos": "dgt.","vn": "nhìn thấy"},{"hanzi": "桌子","pinyin": "zhuōzi","pos": "dt.","vn": "cái bàn"},{"hanzi": "下","pinyin": "xià","pos": "dt.","vn": "dưới, phía dưới"},{"hanzi": "漂亮","pinyin": "piàoliang","pos": "tt.","vn": "xinh đẹp"},{"hanzi": "在","pinyin": "zài","pos": "giới.","vn": "ở, tại"},{"hanzi": "学校","pinyin": "xuéxiào","pos": "dt.","vn": "trường học"},{"hanzi": "书店","pinyin": "shūdiàn","pos": "dt.","vn": "hiệu sách"},{"hanzi": "前","pinyin": "qián","pos": "dt.","vn": "trước, phía trước"},{"hanzi": "能","pinyin": "néng","pos": "đtnn.","vn": "có thể"},{"hanzi": "到","pinyin": "dào","pos": "dgt.","vn": "đến, tới"},{"hanzi": "午饭","pinyin": "wǔfàn","pos": "dt.","vn": "bữa trưa"},{"hanzi": "饭","pinyin": "fàn","pos": "dt.","vn": "cơm, bữa ăn"},{"hanzi": "大","pinyin": "dà","pos": "tt.","vn": "to, lớn"},{"hanzi": "病人","pinyin": "bìngrén","pos": "dt.","vn": "bệnh nhân"},{"hanzi": "多","pinyin": "duō","pos": "tt.","vn": "nhiều"},{"hanzi": "医生","pinyin": "yīshēng","pos": "dt.","vn": "bác sĩ"},{"hanzi": "工作","pinyin": "gōngzuò","pos": "dgt.","vn": "làm việc"},{"hanzi": "胡医生","pinyin": "Hú yīshēng","pos": "danh từ riêng","vn": "Bác sĩ Hồ"}],"grammar": [{"title": "方位词","explanation_vn": "Các từ chỉ phương vị biểu đạt phương hướng, vị trí được học trong tập này gồm: 上, 下, 里, 外, 前, 后, 外边.","examples": [{"cn": "房间里有一只小猫。","pinyin": "Fángjiān li yǒu yì zhī xiǎo māo.","vn": "Trong phòng có một con mèo nhỏ."},{"cn": "我们去书店外吧。","pinyin": "Wǒmen qù shūdiàn wài ba.","vn": "Chúng ta ra ngoài hiệu sách đi."},{"cn": "小雪的手机在桌子上呢。","pinyin": "Xiǎoxuě de shǒujī zài zhuōzi shang ne.","vn": "Điện thoại của Tiểu Tuyết đang ở trên bàn đấy."}]},{"title": "介词“在”","explanation_vn": "Giới từ \"在\" kết hợp với từ ngữ chỉ vị trí, nơi chốn, đứng trước động từ, biểu thị làm việc gì đó ở vị trí, nơi chốn nào.","examples": [{"cn": "我在学校吃午饭。","pinyin": "Wǒ zài xuéxiào chī wǔfàn.","vn": "Tôi ăn trưa ở trường."},{"cn": "他爸爸在医院工作。","pinyin": "Tā bàba zài yīyuàn gōngzuò.","vn": "Bố anh ấy làm việc ở bệnh viện."},{"cn": "你在哪儿买菜？","pinyin": "Nǐ zài nǎr mǎi cài?","vn": "Bạn mua rau ở đâu?"}]},{"title": "能愿动词“能”","explanation_vn": "Động từ năng nguyện \"能\" đứng trước động từ, biểu thị có năng lực, có điều kiện hoặc có khả năng làm việc gì đó.","examples": [{"cn": "下午两点你能到吗？","pinyin": "Xiàwǔ liǎng diǎn nǐ néng dào ma?","vn": "Hai giờ chiều bạn đến được không?"},{"cn": "爸爸能去。","pinyin": "Bàba néng qù.","vn": "Bố có thể đi được."},{"cn": "我不能去学校吃午饭。","pinyin": "Wǒ bù néng qù xuéxiào chī wǔfàn.","vn": "Tôi không thể đến trường ăn trưa được."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "白家月","cn": "房间外有一只小猫。","pinyin": "Fángjiān wài yǒu yì zhī xiǎo māo."},{"speaker": "陈天中","cn": "我没看见，它在哪儿呢？","pinyin": "Wǒ méi kànjiàn, tā zài nǎr ne?"},{"speaker": "白家月","cn": "它在桌子下呢。","pinyin": "Tā zài zhuōzi xià ne."},{"speaker": "陈天中","cn": "这只小猫真漂亮！","pinyin": "Zhè zhī xiǎo māo zhēn piàoliang!"}],"translation_vn": "Bạch Gia Nguyệt: Ngoài phòng có một con mèo nhỏ.\nTrần Thiên Trung: Tôi không nhìn thấy, nó ở đâu vậy?\nBạch Gia Nguyệt: Nó đang ở dưới bàn kìa.\nTrần Thiên Trung: Con mèo này thật đáng yêu!","audio_dialogue": "8-1.mp3","audio_vocab": "8-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "白家月","cn": "我们在哪儿见呢？","pinyin": "Wǒmen zài nǎr jiàn ne?"},{"speaker": "李文","cn": "在学校书店前见吧。","pinyin": "Zài xuéxiào shūdiàn qián jiàn ba."},{"speaker": "白家月","cn": "好的。下午两点你能到吗？","pinyin": "Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?"},{"speaker": "李文","cn": "我能到。我在学校吃午饭。","pinyin": "Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn."}],"translation_vn": "Bạch Gia Nguyệt: Chúng ta gặp nhau ở đâu nhỉ?\nLý Văn: Gặp nhau trước hiệu sách của trường nhé.\nBạch Gia Nguyệt: Được. Hai giờ chiều bạn đến được không?\nLý Văn: Tôi đến được. Tôi ăn trưa ở trường.","audio_dialogue": "8-3.mp3","audio_vocab": "8-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "刘明","cn": "小胡，还没吃饭呢？","pinyin": "Xiǎo Hú, hái méi chī fàn ne?"},{"speaker": "胡医生","cn": "没吃呢。","pinyin": "Méi chī ne."},{"speaker": "刘明","cn": "大医院病人多，医生非常忙。","pinyin": "Dà yīyuàn bìngrén duō, yīshēng fēicháng máng."},{"speaker": "胡医生","cn": "是的。我爸爸也在医院工作，他也非常忙。","pinyin": "Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng."},{"speaker": "刘明","cn": "你家有两个医生？","pinyin": "Nǐ jiā yǒu liǎng gè yīshēng?"},{"speaker": "胡医生","cn": "对。","pinyin": "Duì."}],"translation_vn": "Lưu Minh: Tiểu Hồ, vẫn chưa ăn cơm à?\nBác sĩ Hồ: Chưa ăn.\nLưu Minh: Bệnh viện lớn nhiều bệnh nhân, bác sĩ rất bận rộn.\nBác sĩ Hồ: Đúng vậy. Bố tôi cũng làm việc ở bệnh viện, ông ấy cũng rất bận.\nLưu Minh: Nhà bạn có hai bác sĩ à?\nBác sĩ Hồ: Đúng vậy.","audio_dialogue": "8-5.mp3","audio_vocab": "8-6.mp3"}]},{"id": 9,"title_cn": "我明天上午在学校学习","title_pinyin": "Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí","title_vn": "Ngày mai sáng tôi học ở trường","goals": ["Có thể nghe hiểu và sử dụng \"有/是\" để biểu thị sự tồn tại.","Nắm vững trật tự khi từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn cùng xuất hiện làm trạng ngữ.","Nắm vững cách dùng \"第\".","Hiểu biết về các hoạt động giải trí của người Trung Quốc hiện đại."],"vocab": [{"hanzi": "前边","pinyin": "qiánbian","pos": "dt.","vn": "phía trước"},{"hanzi": "边","pinyin": "bian/biān","pos": "htố.","vn": "bên, phía"},{"hanzi": "家","pinyin": "jiā","pos": "lượng.","vn": "lượng từ dùng cho gia đình, cơ sở kinh doanh"},{"hanzi": "那个","pinyin": "nàge","pos": "đt.","vn": "cái đó, cái kia"},{"hanzi": "外边","pinyin": "wàibian","pos": "dt.","vn": "bên ngoài"},{"hanzi": "椅子","pinyin": "yǐzi","pos": "dt.","vn": "cái ghế"},{"hanzi": "上","pinyin": "shang/shàng","pos": "dt.","vn": "trên"},{"hanzi": "本","pinyin": "běn","pos": "lượng.","vn": "quyển, cuốn"},{"hanzi": "书","pinyin": "shū","pos": "dt.","vn": "sách"},{"hanzi": "那","pinyin": "nà","pos": "đt.","vn": "đó, kia"},{"hanzi": "第","pinyin": "dì","pos": "ttố.","vn": "thứ (tiền tố tạo số thứ tự)"},{"hanzi": "学习","pinyin": "xuéxí","pos": "dgt.","vn": "học tập"},{"hanzi": "做","pinyin": "zuò","pos": "dgt.","vn": "làm"},{"hanzi": "白天","pinyin": "báitiān","pos": "dt.","vn": "ban ngày"},{"hanzi": "读书","pinyin": "dúshū","pos": "dgt.","vn": "đọc sách"},{"hanzi": "和","pinyin": "hé","pos": "giới.","vn": "với, và"},{"hanzi": "朋友","pinyin": "péngyou","pos": "dt.","vn": "bạn bè"},{"hanzi": "唱","pinyin": "chàng","pos": "dgt.","vn": "hát"},{"hanzi": "歌","pinyin": "gē","pos": "dt.","vn": "bài hát"},{"hanzi": "好听","pinyin": "hǎotīng","pos": "tt.","vn": "hay, dễ nghe"},{"hanzi": "电视","pinyin": "diànshì","pos": "dt.","vn": "ti vi"},{"hanzi": "狗","pinyin": "gǒu","pos": "dt.","vn": "chó"},{"hanzi": "玩","pinyin": "wán","pos": "dgt.","vn": "chơi"}],"grammar": [{"title": "存现句（1）","explanation_vn": "Câu tồn hiện là câu biểu thị một địa điểm hoặc vị trí nào đó tồn tại người hoặc vật, thường dùng \"有\" hoặc \"是\" làm dấu hiệu. Khi phủ định, không dùng số từ - lượng từ trước tân ngữ.","examples": [{"cn": "学校前边有一家电影院。","pinyin": "Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vn": "Phía trước trường có một rạp chiếu phim."},{"cn": "电影院前边是一家超市。","pinyin": "Diànyǐngyuàn qiánbian shì yì jiā chāoshì.","vn": "Phía trước rạp chiếu phim là một siêu thị."},{"cn": "桌子上没有小猫。","pinyin": "Zhuōzi shang méiyǒu xiǎo māo.","vn": "Trên bàn không có con mèo nào."}]},{"title": "时间词语和处所词语同时作状语的顺序","explanation_vn": "Khi từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn cùng làm trạng ngữ, từ ngữ chỉ thời gian phải đứng trước từ ngữ chỉ nơi chốn.","examples": [{"cn": "我们七点在电影院外边见。","pinyin": "Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn.","vn": "Chúng ta gặp nhau lúc bảy giờ ở ngoài rạp chiếu phim."},{"cn": "安妮下午在家里学中文。","pinyin": "Ānnī xiàwǔ zài jiā li xué Zhōngwén.","vn": "Chiều nay Annie học tiếng Trung ở nhà."},{"cn": "陈天中明天中午在学校吃午饭。","pinyin": "Chén Tiānzhōng míngtiān zhōngwǔ zài xuéxiào chī wǔfàn.","vn": "Trưa mai Trần Thiên Trung ăn trưa ở trường."}]},{"title": "表示序数的“第”","explanation_vn": "\"第\" đứng trước số từ chỉ số nguyên, biểu thị số thứ tự. Cấu trúc cơ bản: (1) 第 + số từ; (2) 第 + số từ + lượng từ + (danh từ).","examples": [{"cn": "第一，第二，第三。","pinyin": "Dì-yī, dì-èr, dì-sān.","vn": "Thứ nhất, thứ hai, thứ ba."},{"cn": "第一个，第二个，第一本。","pinyin": "Dì-yī gè, dì-èr gè, dì-yī běn.","vn": "Cái thứ nhất, cái thứ hai, quyển thứ nhất."},{"cn": "第一个学生，第一本书。","pinyin": "Dì-yī gè xuésheng, dì-yī běn shū.","vn": "Học sinh thứ nhất, quyển sách thứ nhất."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "李文","cn": "学校前边有一家电影院。","pinyin": "Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn."},{"speaker": "白家月","cn": "对。我们晚上去那个电影院看电影吧。","pinyin": "Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba."},{"speaker": "李文","cn": "好！我们七点在电影院外边见，好吗？","pinyin": "Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?"},{"speaker": "白家月","cn": "好的，晚上七点见！","pinyin": "Hǎo de, wǎnshang qī diǎn jiàn!"}],"translation_vn": "Lý Văn: Phía trước trường có một rạp chiếu phim.\nBạch Gia Nguyệt: Đúng vậy. Tối nay chúng ta đi rạp đó xem phim nhé.\nLý Văn: Được! Chúng ta gặp nhau lúc bảy giờ ở ngoài rạp chiếu phim nhé?\nBạch Gia Nguyệt: Được, bảy giờ tối gặp nhau nhé!","audio_dialogue": "9-1.mp3","audio_vocab": "9-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "白家月","cn": "椅子上有一本中文书，那是谁的书？","pinyin": "Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?"},{"speaker": "陈天中","cn": "是我的书，谢谢。这是我的第二本中文书。","pinyin": "Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū."},{"speaker": "白家月","cn": "不客气。你明天上午在哪儿？","pinyin": "Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?"},{"speaker": "陈天中","cn": "我明天上午在学校学习。","pinyin": "Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí."}],"translation_vn": "Bạch Gia Nguyệt: Trên ghế có một quyển sách tiếng Trung, đó là sách của ai vậy?\nTrần Thiên Trung: Là sách của tôi, cảm ơn bạn. Đây là quyển sách tiếng Trung thứ hai của tôi.\nBạch Gia Nguyệt: Không có gì. Sáng mai bạn ở đâu?\nTrần Thiên Trung: Sáng mai tôi học ở trường.","audio_dialogue": "9-3.mp3","audio_vocab": "9-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一雪","cn": "明天星期六，你做什么？","pinyin": "Míngtiān xīngqīliù, nǐ zuò shénme?"},{"speaker": "杨同乐","cn": "我白天在家里读书，晚上和朋友们去外边唱歌。","pinyin": "Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē."},{"speaker": "王一雪","cn": "你唱歌很好听。","pinyin": "Nǐ chàng gē hěn hǎotīng."},{"speaker": "杨同乐","cn": "谢谢！您星期六做什么？","pinyin": "Xièxie! Nín xīngqīliù zuò shénme?"},{"speaker": "王一雪","cn": "我在家里做饭、看电视，和孩子们、小狗玩。","pinyin": "Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán."},{"speaker": "杨同乐","cn": "我也有一只小狗。","pinyin": "Wǒ yě yǒu yì zhī xiǎo gǒu."}],"translation_vn": "Vương Nhất Tuyết: Ngày mai là thứ Bảy, bạn định làm gì?\nDương Đồng Lạc: Ban ngày tôi ở nhà đọc sách, buổi tối cùng bạn bè ra ngoài hát.\nVương Nhất Tuyết: Bạn hát hay lắm.\nDương Đồng Lạc: Cảm ơn! Thứ Bảy chị làm gì?\nVương Nhất Tuyết: Tôi ở nhà nấu cơm, xem ti vi, chơi với các con và chó con.\nDương Đồng Lạc: Tôi cũng có một chú chó con.","audio_dialogue": "9-5.mp3","audio_vocab": "9-6.mp3"}]},{"id": 10,"title_cn": "这儿的苹果真便宜！","title_pinyin": "Zhèr de píngguǒ zhēn piányi!","title_vn": "Táo ở đây rẻ thật đấy!","goals": ["Có thể nghe hiểu, đọc hiểu và nói đơn giản về giá cả hàng hóa.","Nắm vững cách dùng câu có vị ngữ là tính từ.","Nắm vững cách dùng đại từ nghi vấn \"怎么样\".","Nhận biết đồng Nhân dân tệ (RMB)."],"vocab": [{"hanzi": "杯子","pinyin": "bēizi","pos": "dt.","vn": "cốc, ly"},{"hanzi": "售货员","pinyin": "shòuhuòyuán","pos": "dt.","vn": "nhân viên bán hàng"},{"hanzi": "这边","pinyin": "zhèbiān","pos": "đt.","vn": "bên này"},{"hanzi": "钱","pinyin": "qián","pos": "dt.","vn": "tiền"},{"hanzi": "这些","pinyin": "zhèxiē","pos": "đt.","vn": "những cái này"},{"hanzi": "块","pinyin": "kuài","pos": "lượng.","vn": "đồng, tệ (dùng khi nói về tiền)"},{"hanzi": "那些","pinyin": "nàxiē","pos": "đt.","vn": "những cái kia"},{"hanzi": "这儿","pinyin": "zhèr","pos": "đt.","vn": "ở đây"},{"hanzi": "水果","pinyin": "shuǐguǒ","pos": "dt.","vn": "hoa quả, trái cây"},{"hanzi": "少","pinyin": "shǎo","pos": "tt.","vn": "ít"},{"hanzi": "斤","pinyin": "jīn","pos": "lượng.","vn": "cân (jin, đơn vị trọng lượng Trung Quốc)"},{"hanzi": "苹果","pinyin": "píngguǒ","pos": "dt.","vn": "táo"},{"hanzi": "便宜","pinyin": "piányi","pos": "tt.","vn": "rẻ"},{"hanzi": "商店","pinyin": "shāngdiàn","pos": "dt.","vn": "cửa hàng"},{"hanzi": "衣服","pinyin": "yīfu","pos": "dt.","vn": "quần áo"},{"hanzi": "件","pinyin": "jiàn","pos": "lượng.","vn": "cái, chiếc (dùng cho quần áo)"},{"hanzi": "元","pinyin": "yuán","pos": "lượng.","vn": "tệ, nguyên (đơn vị tiền tệ)"},{"hanzi": "怎么样","pinyin": "zěnmeyàng","pos": "đt.","vn": "thế nào, như thế nào"},{"hanzi": "贵","pinyin": "guì","pos": "tt.","vn": "đắt"},{"hanzi": "穿","pinyin": "chuān","pos": "dgt.","vn": "mặc"},{"hanzi": "女","pinyin": "nǚ","pos": "tt.","vn": "nữ, con gái"},{"hanzi": "男","pinyin": "nán","pos": "tt.","vn": "nam, con trai"},{"hanzi": "那儿","pinyin": "nàr","pos": "đt.","vn": "ở đó, đằng kia"}],"grammar": [{"title": "钱数的表达","explanation_vn": "Tiền tệ Trung Quốc gọi là Nhân dân tệ (人民币). Đơn vị tiền tệ từ lớn đến nhỏ là \"元, 角, 分\", trong khẩu ngữ lần lượt gọi là \"块, 毛, 分\". Thứ tự biểu đạt là: 元/块 → 角/毛 → 分.","examples": [{"cn": "3元 / 三块","pinyin": "sān kuài","vn": "3 tệ (ba đồng)"},{"cn": "3.2元 / 三块二","pinyin": "sān kuài èr","vn": "3,2 tệ (ba đồng hai)"},{"cn": "6.02元 / 六块零两分","pinyin": "liù kuài líng liǎng fēn","vn": "6,02 tệ (sáu đồng lẻ hai xu)"},{"cn": "202.2元 / 二百零二块两毛","pinyin": "èrbǎi líng èr kuài liǎng máo","vn": "202,2 tệ (hai trăm lẻ hai đồng hai hào)"}]},{"title": "形容词谓语句","explanation_vn": "Tính từ có thể trực tiếp làm vị ngữ trong câu, phía trước có thể thêm phó từ chỉ mức độ hoặc phó từ phủ định.","examples": [{"cn": "这儿的水果真不少！","pinyin": "Zhèr de shuǐguǒ zhēn bù shǎo!","vn": "Hoa quả ở đây nhiều thật đấy!"},{"cn": "我的房间不大。","pinyin": "Wǒ de fángjiān bú dà.","vn": "Phòng của tôi không rộng."},{"cn": "那个苹果好吃。","pinyin": "Nàge píngguǒ hǎochī.","vn": "Quả táo đó ngon."}]},{"title": "疑问代词“怎么样”","explanation_vn": "Đại từ nghi vấn \"怎么样\" dùng để hỏi ý kiến, hỏi về tình trạng, v.v. Cấu trúc cơ bản: ……怎么样?","examples": [{"cn": "这个杯子怎么样？我很喜欢，也不贵。","pinyin": "Zhège bēizi zěnmeyàng? Wǒ hěn xǐhuan, yě bú guì.","vn": "Cái cốc này thế nào? Tôi rất thích, cũng không đắt."},{"cn": "这本书怎么样？很好看。","pinyin": "Zhè běn shū zěnmeyàng? Hěn hǎokàn.","vn": "Quyển sách này thế nào? Rất hay."},{"cn": "这个菜怎么样？这个菜不太好吃，我不喜欢。","pinyin": "Zhège cài zěnmeyàng? Zhège cài bú tài hǎochī, wǒ bù xǐhuan.","vn": "Món này thế nào? Món này không ngon lắm, tôi không thích."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "王一雪","cn": "请问，有杯子吗？","pinyin": "Qǐngwèn, yǒu bēizi ma?"},{"speaker": "售货员","cn": "有，杯子在这边。","pinyin": "Yǒu, bēizi zài zhèbiān."},{"speaker": "王一雪","cn": "多少钱一个？","pinyin": "Duōshao qián yí gè?"},{"speaker": "售货员","cn": "这些五块钱一个，那些十块钱一个。","pinyin": "Zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè."},{"speaker": "王一雪","cn": "我买这个吧。","pinyin": "Wǒ mǎi zhège ba."}],"translation_vn": "Vương Nhất Tuyết: Xin hỏi, ở đây có cốc không ạ?\nNhân viên bán hàng: Có, cốc ở bên này ạ.\nVương Nhất Tuyết: Bao nhiêu tiền một cái?\nNhân viên bán hàng: Những cái này năm tệ một cái, những cái kia mười tệ một cái.\nVương Nhất Tuyết: Tôi mua cái này vậy.","audio_dialogue": "10-1.mp3","audio_vocab": "10-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一雪","cn": "这儿的水果真不少！","pinyin": "Zhèr de shuǐguǒ zhēn bù shǎo!"},{"speaker": "售货员","cn": "您想买什么？","pinyin": "Nín xiǎng mǎi shénme?"},{"speaker": "王一雪","cn": "我想买两斤苹果。","pinyin": "Wǒ xiǎng mǎi liǎng jīn píngguǒ."},{"speaker": "售货员","cn": "苹果三块五一斤。这些七块二，七块钱吧。","pinyin": "Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba."},{"speaker": "王一雪","cn": "好的，这儿的苹果真便宜！","pinyin": "Hǎo de, zhèr de píngguǒ zhēn piányi!"}],"translation_vn": "Vương Nhất Tuyết: Ở đây hoa quả nhiều thật đấy!\nNhân viên bán hàng: Chị muốn mua gì ạ?\nVương Nhất Tuyết: Tôi muốn mua hai cân táo.\nNhân viên bán hàng: Táo ba tệ năm một cân. Số này là bảy tệ hai, thôi lấy bảy tệ vậy.\nVương Nhất Tuyết: Được, táo ở đây rẻ thật đấy!","audio_dialogue": "10-3.mp3","audio_vocab": "10-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一雪","cn": "这家商店衣服真多！这件一百元，怎么样？","pinyin": "Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?"},{"speaker": "刘明","cn": "好看，也不贵。","pinyin": "Hǎokàn, yě bú guì."},{"speaker": "王一雪","cn": "小雪能穿，买一件吧。","pinyin": "Xiǎoxuě néng chuān, mǎi yí jiàn ba."},{"speaker": "刘明","cn": "好的。小明能穿吗？","pinyin": "Hǎo de. Xiǎomíng néng chuān ma?"},{"speaker": "王一雪","cn": "不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","pinyin": "Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr."},{"speaker": "刘明","cn": "好的。","pinyin": "Hǎo de."}],"translation_vn": "Vương Nhất Tuyết: Cửa hàng này quần áo nhiều thật đấy! Cái này một trăm tệ, anh thấy thế nào?\nLưu Minh: Đẹp đấy, cũng không đắt.\nVương Nhất Tuyết: Tiểu Tuyết mặc vừa, mua một cái đi.\nLưu Minh: Được. Tiểu Minh mặc được không?\nVương Nhất Tuyết: Không được. Đây là quần áo con gái mặc, quần áo con trai ở đằng kia.\nLưu Minh: Được rồi.","audio_dialogue": "10-5.mp3","audio_vocab": "10-6.mp3"}]},{"id": 11,"title_cn": "我读大学呢","title_pinyin": "Wǒ dú dàxué ne","title_vn": "Em đang học đại học đây","goals": ["Có thể nghe hiểu và sử dụng ba cấu trúc để diễn đạt việc đang làm.","Có thể nghe hiểu và sử dụng dạng câu hỏi chính phản (khẳng định - phủ định) để đặt câu hỏi.","Nắm vững cách dùng động từ năng nguyện \"要\" để diễn đạt ý muốn làm, dự định làm việc gì đó."],"vocab": [{"hanzi": "时候","pinyin": "shíhou","pos": "dt.","vn": "lúc, thời điểm"},{"hanzi": "饭店","pinyin": "fàndiàn","pos": "dt.","vn": "nhà hàng, khách sạn"},{"hanzi": "知道","pinyin": "zhīdào","pos": "dgt.","vn": "biết"},{"hanzi": "正在","pinyin": "zhèngzài","pos": "phó.","vn": "đang"},{"hanzi": "找","pinyin": "zhǎo","pos": "dgt.","vn": "tìm"},{"hanzi": "开车","pinyin": "kāichē","pos": "dgt.","vn": "lái xe"},{"hanzi": "车","pinyin": "chē","pos": "dt.","vn": "xe"},{"hanzi": "在","pinyin": "zài","pos": "phó.","vn": "đang"},{"hanzi": "读","pinyin": "dú","pos": "dgt.","vn": "học, theo học"},{"hanzi": "大学","pinyin": "dàxué","pos": "dt.","vn": "đại học"},{"hanzi": "大学生","pinyin": "dàxuéshēng","pos": "dt.","vn": "sinh viên đại học"},{"hanzi": "学","pinyin": "xué","pos": "dgt.","vn": "học"},{"hanzi": "医","pinyin": "yī","pos": "dt.","vn": "y, y học"},{"hanzi": "弟弟","pinyin": "dìdi","pos": "dt.","vn": "em trai"},{"hanzi": "起床","pinyin": "qǐchuáng","pos": "dgt.","vn": "dậy, thức dậy"},{"hanzi": "睡觉","pinyin": "shuìjiào","pos": "dgt.","vn": "ngủ"},{"hanzi": "睡","pinyin": "shuì","pos": "dgt.","vn": "ngủ"},{"hanzi": "那里","pinyin": "nàlǐ","pos": "đt.","vn": "ở đó"},{"hanzi": "哪里","pinyin": "nǎlǐ","pos": "đt.","vn": "ở đâu"},{"hanzi": "昨天","pinyin": "zuótiān","pos": "dt.","vn": "hôm qua"},{"hanzi": "问","pinyin": "wèn","pos": "dgt.","vn": "hỏi"},{"hanzi": "对","pinyin": "duì","pos": "giới.","vn": "đối với, với"},{"hanzi": "说","pinyin": "shuō","pos": "dgt.","vn": "nói"},{"hanzi": "要","pinyin": "yào","pos": "đtnn.","vn": "muốn, định"},{"hanzi": "小朋友","pinyin": "xiǎopéngyǒu","pos": "dt.","vn": "bạn nhỏ, trẻ con"}],"grammar": [{"title": "正反问","explanation_vn": "Câu hỏi chính phản có cấu trúc \"×+不/没+×\", trong đó \"×\" là động từ hoặc tính từ. Câu hỏi chính phản với động từ dùng \"不/没\", còn với tính từ dùng \"不\".","examples": [{"cn": "它是不是在超市后边？","pinyin": "Tā shì bu shì zài chāoshì hòubian?","vn": "Nó có phải ở phía sau siêu thị không?"},{"cn": "你去没去学校？","pinyin": "Nǐ qù méi qù xuéxiào?","vn": "Anh đã đi học chưa?"},{"cn": "这件衣服好看不好看？","pinyin": "Zhè jiàn yīfu hǎokàn bu hǎokàn?","vn": "Cái áo này có đẹp không?"},{"cn": "他去哪儿了？你知道不知道？","pinyin": "Tā qù nǎr le? Nǐ zhīdào bu zhīdào?","vn": "Anh ấy đi đâu rồi? Em có biết không?"},{"cn": "昨天你去没去书店？","pinyin": "Zuótiān nǐ qù méi qù shūdiàn?","vn": "Hôm qua anh có đi hiệu sách không?"},{"cn": "这件衣服贵不贵？","pinyin": "Zhè jiàn yīfu guì bu guì?","vn": "Cái áo này có đắt không?"}]},{"title": "时间副词“在/正在”","explanation_vn": "Phó từ chỉ thời gian \"在/正在\" đặt trước động từ, biểu thị động tác đang diễn ra hoặc tình huống đang tiếp diễn. Bài học này giới thiệu hai cấu trúc: (1) 在/正在 + động từ; (2) 在/正在 + động từ + 呢. Ngoài ra còn có cấu trúc thứ ba để diễn đạt việc đang làm: (3) động từ + 呢. Khi trả lời phủ định, dùng phó từ \"没(有)\".","examples": [{"cn": "你还在读大学吗？","pinyin": "Nǐ hái zài dú dàxué ma?","vn": "Anh vẫn đang học đại học à?"},{"cn": "学生们在/正在上课呢。","pinyin": "Xuéshengmen zài/zhèngzài shàngkè ne.","vn": "Các học sinh đang học trên lớp."},{"cn": "我们读书呢。","pinyin": "Wǒmen dúshū ne.","vn": "Chúng tôi đang đọc sách."},{"cn": "你在做什么呢？我正在看电视。","pinyin": "Nǐ zài zuò shénme ne? Wǒ zhèngzài kàn diànshì.","vn": "Anh đang làm gì vậy? Tôi đang xem ti vi."},{"cn": "我去看电影，你去不去？我在学习呢，不想去。","pinyin": "Wǒ qù kàn diànyǐng, nǐ qù bu qù? Wǒ zài xuéxí ne, bù xiǎng qù.","vn": "Tôi đi xem phim, anh đi không? Tôi đang học, không muốn đi."},{"cn": "你在买菜吗？我没买菜，买水果呢。","pinyin": "Nǐ zài mǎi cài ma? Wǒ méi mǎi cài, mǎi shuǐguǒ ne.","vn": "Anh đang mua rau à? Tôi không mua rau, đang mua hoa quả."}]},{"title": "能愿动词“要”","explanation_vn": "Động từ năng nguyện \"要\" đứng trước động từ, biểu thị ý muốn làm hoặc dự định làm việc gì đó.","examples": [{"cn": "他今天要和小朋友玩。","pinyin": "Tā jīntiān yào hé xiǎopéngyǒu wán.","vn": "Hôm nay nó định chơi với các bạn."},{"cn": "妈妈要去超市。","pinyin": "Māma yào qù chāoshì.","vn": "Mẹ định đi siêu thị."},{"cn": "白家月要在家里学中文。","pinyin": "Bái Jiāyuè yào zài jiā li xué Zhōngwén.","vn": "Bạch Gia Nguyệt định học tiếng Trung ở nhà."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "王一飞","cn": "喂，李文，你什么时候能到饭店？","pinyin": "Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?"},{"speaker": "李文","cn": "还不知道，正在找呢。它是不是在超市后边？","pinyin": "Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?"},{"speaker": "王一飞","cn": "是的。你开车没开车？","pinyin": "Shì de. Nǐ kāichē méi kāichē?"},{"speaker": "李文","cn": "我没开车，坐车呢。","pinyin": "Wǒ méi kāichē, zuò chē ne."}],"translation_vn": "Vương Nhất Phi: Alô, Lý Văn, khi nào anh đến được nhà hàng?\nLý Văn: Vẫn chưa biết, đang tìm đây. Nó có phải ở phía sau siêu thị không?\nVương Nhất Phi: Đúng vậy. Anh có lái xe không?\nLý Văn: Tôi không lái xe, đang ngồi xe đây.","audio_dialogue": "11-1.mp3","audio_vocab": "11-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一飞","cn": "你还在读大学吗？","pinyin": "Nǐ hái zài dú dàxué ma?"},{"speaker": "李文","cn": "对，我读大学呢，还是大学生。","pinyin": "Duì, wǒ dú dàxué ne, hái shì dàxuéshēng."},{"speaker": "王一飞","cn": "你们学习忙不忙？","pinyin": "Nǐmen xuéxí máng bu máng?"},{"speaker": "李文","cn": "非常忙，我学医，我们的课很多。","pinyin": "Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō."}],"translation_vn": "Vương Nhất Phi: Anh vẫn đang học đại học à?\nLý Văn: Đúng vậy, tôi đang học đại học, vẫn còn là sinh viên.\nVương Nhất Phi: Các bạn học hành có bận không?\nLý Văn: Bận lắm, tôi học y, lớp chúng tôi có rất nhiều tiết học.","audio_dialogue": "11-3.mp3","audio_vocab": "11-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "刘明","cn": "弟弟起床没起床呢？","pinyin": "Dìdi qǐchuáng méi qǐchuáng ne?"},{"speaker": "刘小雪","cn": "没起床呢，还在睡觉。","pinyin": "Méi qǐchuáng ne, hái zài shuìjiào."},{"speaker": "刘明","cn": "还睡呢？他今天去不去那里？","pinyin": "Hái shuì ne? Tā jīntiān qù bu qù nàlǐ?"},{"speaker": "刘小雪","cn": "去哪里？","pinyin": "Qù nǎlǐ?"},{"speaker": "刘明","cn": "去超市。","pinyin": "Qù chāoshì."},{"speaker": "刘小雪","cn": "我昨天问他，他对我说，他不去，他今天要和小朋友玩。","pinyin": "Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán."}],"translation_vn": "Lưu Minh: Em trai dậy chưa?\nLưu Tiểu Tuyết: Chưa dậy đâu, vẫn đang ngủ.\nLưu Minh: Vẫn còn ngủ à? Hôm nay nó có đi đến đó không?\nLưu Tiểu Tuyết: Đi đâu cơ?\nLưu Minh: Đi siêu thị.\nLưu Tiểu Tuyết: Hôm qua con hỏi nó rồi, nó bảo con là nó không đi, hôm nay nó định chơi với bạn.","audio_dialogue": "11-5.mp3","audio_vocab": "11-6.mp3"}]},{"id": 12,"title_cn": "昨天下雪了","title_pinyin": "Zuótiān xià xuě le","title_vn": "Hôm qua trời đã có tuyết","goals": ["Có thể nghe hiểu và miêu tả tình hình thời tiết.","Có thể nghe hiểu và miêu tả đơn giản về tình trạng bệnh.","Nắm vững cách dùng trợ từ ngữ khí \"了(1)\".","Nắm vững cách dùng cấu trúc \"太……了\".","Hiểu được lợi ích của việc \"uống nước ấm\" mà người Trung Quốc thường khuyên khi bị ốm."],"vocab": [{"hanzi": "天气","pinyin": "tiānqì","pos": "dt.","vn": "thời tiết"},{"hanzi": "这里","pinyin": "zhèlǐ","pos": "đt.","vn": "ở đây"},{"hanzi": "天","pinyin": "tiān","pos": "dt.","vn": "trời, thời tiết"},{"hanzi": "下雨","pinyin": "xià yǔ","pos": "","vn": "trời mưa, đổ mưa"},{"hanzi": "了","pinyin": "le","pos": "trợ.","vn": "trợ từ ngữ khí, đặt cuối câu biểu thị có sự thay đổi hoặc xuất hiện tình huống mới"},{"hanzi": "雨","pinyin": "yǔ","pos": "dt.","vn": "mưa"},{"hanzi": "有点儿","pinyin": "yǒudiǎnr","pos": "phó.","vn": "hơi, một chút"},{"hanzi": "觉得","pinyin": "juéde","pos": "dgt.","vn": "cảm thấy"},{"hanzi": "冷","pinyin": "lěng","pos": "tt.","vn": "lạnh"},{"hanzi": "下","pinyin": "xià","pos": "dgt.","vn": "rơi, đổ xuống (mưa, tuyết...)"},{"hanzi": "雪","pinyin": "xuě","pos": "dt.","vn": "tuyết"},{"hanzi": "来","pinyin": "lái","pos": "dgt.","vn": "đến"},{"hanzi": "公司","pinyin": "gōngsī","pos": "dt.","vn": "công ty"},{"hanzi": "生病","pinyin": "shēngbìng","pos": "dgt.","vn": "bị ốm, bị bệnh"},{"hanzi": "看病","pinyin": "kànbìng","pos": "dgt.","vn": "khám bệnh"},{"hanzi": "病","pinyin": "bìng","pos": "dgt.","vn": "ốm, bị bệnh"},{"hanzi": "一点儿","pinyin": "yìdiǎnr","pos": "sl.","vn": "một chút, một ít"},{"hanzi": "药","pinyin": "yào","pos": "dt.","vn": "thuốc"},{"hanzi": "天","pinyin": "tiān","pos": "lượng.","vn": "ngày (lượng từ chỉ ngày)"},{"hanzi": "回","pinyin": "huí","pos": "dgt.","vn": "trở về, quay về"},{"hanzi": "再","pinyin": "zài","pos": "phó.","vn": "rồi hãy, mới (sau đó mới)"},{"hanzi": "喝","pinyin": "hē","pos": "dgt.","vn": "uống"},{"hanzi": "热","pinyin": "rè","pos": "tt.","vn": "nóng, ấm"},{"hanzi": "水","pinyin": "shuǐ","pos": "dt.","vn": "nước"}],"grammar": [{"title": "非主谓句","explanation_vn": "Câu phi chủ vị là loại câu được cấu tạo bởi từ hoặc cụm từ, không phân biệt rõ chủ ngữ và vị ngữ, thường được dùng trong khẩu ngữ.","examples": [{"cn": "下雨了。","pinyin": "Xià yǔ le.","vn": "Trời mưa rồi."},{"cn": "下雪了。","pinyin": "Xià xuě le.","vn": "Trời có tuyết rồi."},{"cn": "上课了。","pinyin": "Shàng kè le.","vn": "Đến giờ học rồi."},{"cn": "真漂亮！","pinyin": "Zhēn piàoliang!","vn": "Đẹp quá!"},{"cn": "对不起！","pinyin": "Duìbuqǐ!","vn": "Xin lỗi!"},{"cn": "没关系！","pinyin": "Méi guānxi!","vn": "Không sao!"}]},{"title": "语气助词“了(1)”","explanation_vn": "Trợ từ ngữ khí \"了(1)\" đặt ở cuối câu hoặc chỗ ngắt trong câu, biểu thị có sự thay đổi hoặc xuất hiện tình huống mới. Khi trả lời phủ định, dùng phó từ \"没\", cuối câu không dùng \"了\".","examples": [{"cn": "下雨了。","pinyin": "Xià yǔ le.","vn": "Trời mưa rồi."},{"cn": "十二点了，吃午饭吧。","pinyin": "Shí'èr diǎn le, chī wǔfàn ba.","vn": "12 giờ rồi, ăn cơm trưa thôi."},{"cn": "弟弟起床了吗？没起床呢。","pinyin": "Dìdi qǐchuáng le ma? Méi qǐchuáng ne.","vn": "Em trai dậy chưa? Chưa dậy đâu."}]},{"title": "“太……了”格式","explanation_vn": "Cấu trúc \"太……了\" dùng để diễn tả cảm thán với mức độ rất cao hoặc rất sâu sắc.","examples": [{"cn": "太冷了！","pinyin": "Tài lěng le!","vn": "Lạnh quá!"},{"cn": "这个杯子太小了。","pinyin": "Zhège bēizi tài xiǎo le.","vn": "Cái cốc này nhỏ quá."},{"cn": "我们今天太高兴了！","pinyin": "Wǒmen jīntiān tài gāoxìng le!","vn": "Hôm nay chúng tôi vui quá!"}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "王一雪","cn": "今天天气怎么样？","pinyin": "Jīntiān tiānqì zěnmeyàng?"},{"speaker": "王一飞","cn": "这里的天不太好，下雨了。","pinyin": "Zhèlǐ de tiān bú tài hǎo, xià yǔ le."},{"speaker": "王一雪","cn": "雨大吗？","pinyin": "Yǔ dà ma?"},{"speaker": "王一飞","cn": "有点儿大，我觉得很冷。","pinyin": "Yǒudiǎnr dà, wǒ juéde hěn lěng."}],"translation_vn": "Vương Nhất Tuyết: Hôm nay thời tiết thế nào?\nVương Nhất Phi: Thời tiết ở đây không tốt lắm, trời đang mưa.\nVương Nhất Tuyết: Mưa to không?\nVương Nhất Phi: Hơi to, anh thấy lạnh lắm.","audio_dialogue": "12-1.mp3","audio_vocab": "12-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一雪","cn": "昨天下雪了。","pinyin": "Zuótiān xià xuě le."},{"speaker": "杨同乐","cn": "是的，太冷了。","pinyin": "Shì de, tài lěng le."},{"speaker": "王一雪","cn": "你昨天没来公司，生病了？","pinyin": "Nǐ zuótiān méi lái gōngsī, shēngbìng le?"},{"speaker": "杨同乐","cn": "对，我昨天去医院看病了。","pinyin": "Duì, wǒ zuótiān qù yīyuàn kànbìng le."}],"translation_vn": "Vương Nhất Tuyết: Hôm qua trời có tuyết.\nDương Đồng Lạc: Đúng vậy, lạnh quá.\nVương Nhất Tuyết: Hôm qua anh không đến công ty, bị ốm à?\nDương Đồng Lạc: Đúng, hôm qua tôi đi bệnh viện khám bệnh.","audio_dialogue": "12-3.mp3","audio_vocab": "12-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "杨同乐","cn": "医生，我病了。","pinyin": "Yīshēng, wǒ bìng le."},{"speaker": "胡医生","cn": "我看看。你觉得怎么样？","pinyin": "Wǒ kànkan. Nǐ juéde zěnmeyàng?"},{"speaker": "杨同乐","cn": "我很冷。","pinyin": "Wǒ hěn lěng."},{"speaker": "胡医生","cn": "好的，吃一点儿药，今天休息半天吧。","pinyin": "Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba."},{"speaker": "杨同乐","cn": "好的。","pinyin": "Hǎo de."},{"speaker": "胡医生","cn": "回家后再喝些热水。","pinyin": "Huí jiā hòu zài hē xiē rè shuǐ."}],"translation_vn": "Dương Đồng Lạc: Bác sĩ ơi, tôi bị ốm rồi.\nBác sĩ Hồ: Để tôi xem nào. Anh thấy thế nào?\nDương Đồng Lạc: Tôi thấy lạnh lắm.\nBác sĩ Hồ: Được rồi, uống một ít thuốc, hôm nay nghỉ nửa ngày nhé.\nDương Đồng Lạc: Vâng ạ.\nBác sĩ Hồ: Về nhà rồi uống thêm ít nước ấm nhé.","audio_dialogue": "12-5.mp3","audio_vocab": "12-6.mp3"}]},{"id": 13,"title_cn": "请给我一杯茶","title_pinyin": "Qǐng gěi wǒ yì bēi chá","title_vn": "Làm ơn cho tôi một cốc trà","goals": ["Có thể nghe hiểu và sử dụng câu song tân ngữ (1) để diễn đạt việc hỏi người khác hoặc cho người khác đồ vật, v.v.","Nắm vững cách dùng động từ năng nguyện \"可以\".","Nắm vững cách dùng cấu trúc \"động từ + 一下\".","Hiểu các cách diễn đạt thường dùng khi gọi món ăn."],"vocab": [{"hanzi": "可以","pinyin": "kěyǐ","pos": "đtnn.","vn": "có thể, được phép"},{"hanzi": "再","pinyin": "zài","pos": "phó.","vn": "lại, thêm nữa"},{"hanzi": "问题","pinyin": "wèntí","pos": "dt.","vn": "câu hỏi, vấn đề"},{"hanzi": "卖","pinyin": "mài","pos": "dgt.","vn": "bán"},{"hanzi": "打电话","pinyin": "dǎ diànhuà","pos": "","vn": "gọi điện thoại"},{"hanzi": "一下","pinyin": "yíxià","pos": "sl.","vn": "một chút, một lát, thử xem"},{"hanzi": "服务员","pinyin": "fúwùyuán","pos": "dt.","vn": "nhân viên phục vụ"},{"hanzi": "女士","pinyin": "nǚshì","pos": "dt.","vn": "quý bà, cô"},{"hanzi": "请","pinyin": "qǐng","pos": "dgt.","vn": "mời, xin mời"},{"hanzi": "坐","pinyin": "zuò","pos": "dgt.","vn": "ngồi"},{"hanzi": "给","pinyin": "gěi","pos": "dgt.","vn": "cho, đưa"},{"hanzi": "杯","pinyin": "bēi","pos": "dt.","vn": "cốc, ly"},{"hanzi": "要","pinyin": "yào","pos": "dgt.","vn": "muốn, gọi (món)"},{"hanzi": "早饭","pinyin": "zǎofàn","pos": "dt.","vn": "bữa sáng"},{"hanzi": "这个","pinyin": "zhège","pos": "đt.","vn": "cái này"},{"hanzi": "面包","pinyin": "miànbāo","pos": "dt.","vn": "bánh mì"},{"hanzi": "鸡蛋","pinyin": "jīdàn","pos": "dt.","vn": "trứng gà"},{"hanzi": "先生","pinyin": "xiānsheng","pos": "dt.","vn": "ông, quý ông"},{"hanzi": "一半","pinyin": "yíbàn","pos": "số.","vn": "một nửa"},{"hanzi": "茶","pinyin": "chá","pos": "dt.","vn": "trà"}],"grammar": [{"title": "能愿动词“可以”","explanation_vn": "Động từ năng nguyện \"可以\" đứng trước động từ, biểu thị khả năng, năng lực hoặc sự cho phép.","examples": [{"cn": "我可以再问您一个问题吗？","pinyin": "Wǒ kěyǐ zài wèn nín yí gè wèntí ma?","vn": "Em có thể hỏi cô thêm một câu hỏi được không ạ?"},{"cn": "你们可以看这本书。","pinyin": "Nǐmen kěyǐ kàn zhè běn shū.","vn": "Các em có thể xem quyển sách này."},{"cn": "A：我可以坐吗？B：可以，请坐！","pinyin": "A: Wǒ kěyǐ zuò ma? B: Kěyǐ, qǐng zuò!","vn": "A: Tôi ngồi được không? B: Được, mời ngồi!"}]},{"title": "“动词+一下”结构","explanation_vn": "Trong bài này, cấu trúc \"động từ + 一下\" biểu thị một hành động được thực hiện thử hoặc diễn ra trong thời gian ngắn.","examples": [{"cn": "你可以打电话问一下。","pinyin": "Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vn": "Bạn có thể gọi điện hỏi thử xem."},{"cn": "请休息一下。","pinyin": "Qǐng xiūxi yíxià.","vn": "Mời nghỉ một chút."},{"cn": "你看一下吧。","pinyin": "Nǐ kàn yíxià ba.","vn": "Bạn xem thử xem."}]},{"title": "双宾语句（1）","explanation_vn": "Câu song tân ngữ là câu mà một động từ mang theo hai tân ngữ. Trong quyển này, chúng ta học câu song tân ngữ được tạo thành bởi \"给\" và \"问\".","examples": [{"cn": "请给我一杯牛奶。","pinyin": "Qǐng gěi wǒ yì bēi niúnǎi.","vn": "Làm ơn cho tôi một cốc sữa."},{"cn": "白家月给安妮一个苹果。","pinyin": "Bái Jiāyuè gěi Ānnī yí gè píngguǒ.","vn": "Bạch Gia Nguyệt cho Annie một quả táo."},{"cn": "我问老师两个问题。","pinyin": "Wǒ wèn lǎoshī liǎng gè wèntí.","vn": "Tôi hỏi thầy/cô hai câu hỏi."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "白家月","cn": "王老师，我可以再问您一个问题吗？","pinyin": "Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí gè wèntí ma?"},{"speaker": "王一飞","cn": "可以。你有什么问题？","pinyin": "Kěyǐ. Nǐ yǒu shénme wèntí?"},{"speaker": "白家月","cn": "那个小店卖不卖手机？","pinyin": "Nàge xiǎo diàn mài bu mài shǒujī?"},{"speaker": "王一飞","cn": "我不知道。你可以打电话问一下。","pinyin": "Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià."}],"translation_vn": "Bạch Gia Nguyệt: Cô Vương ơi, em có thể hỏi cô thêm một câu được không ạ?\nVương Nhất Phi: Được chứ. Em có câu hỏi gì?\nBạch Gia Nguyệt: Cửa hàng nhỏ đó có bán điện thoại di động không ạ?\nVương Nhất Phi: Cô không biết. Em có thể gọi điện hỏi thử xem.","audio_dialogue": "13-1.mp3","audio_vocab": "13-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "服务员","cn": "女士，请坐！您喝什么？","pinyin": "Nǚshì, qǐng zuò! Nín hē shénme?"},{"speaker": "王一雪","cn": "我看一下。请给我一杯牛奶。","pinyin": "Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi."},{"speaker": "服务员","cn": "好的。您还要什么？","pinyin": "Hǎo de. Nín hái yào shénme?"},{"speaker": "王一雪","cn": "我还没吃早饭，再要这个面包和鸡蛋吧。","pinyin": "Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba."}],"translation_vn": "Phục vụ: Thưa quý cô, mời ngồi! Cô muốn uống gì ạ?\nVương Nhất Tuyết: Để tôi xem đã. Cho tôi một cốc sữa.\nPhục vụ: Vâng ạ. Cô còn muốn dùng gì nữa không?\nVương Nhất Tuyết: Tôi vẫn chưa ăn sáng, cho tôi thêm bánh mì và trứng này nữa nhé.","audio_dialogue": "13-3.mp3","audio_vocab": "13-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "服务员","cn": "先生，请坐！您要什么？","pinyin": "Xiānsheng, qǐng zuò! Nín yào shénme?"},{"speaker": "刘明","cn": "我要一斤饺子。","pinyin": "Wǒ yào yì jīn jiǎozi."},{"speaker": "服务员","cn": "好的。一斤饺子40个。","pinyin": "Hǎo de. Yì jīn jiǎozi sìshí gè."},{"speaker": "刘明","cn": "40个太多了，我要一半吧。","pinyin": "Sìshí gè tài duō le, wǒ yào yíbàn ba."},{"speaker": "服务员","cn": "半斤20个。您想喝什么？","pinyin": "Bàn jīn èrshí gè. Nín xiǎng hē shénme?"},{"speaker": "刘明","cn": "请给我一杯茶吧。","pinyin": "Qǐng gěi wǒ yì bēi chá ba."}],"translation_vn": "Phục vụ: Thưa ông, mời ngồi! Ông muốn dùng gì ạ?\nLưu Minh: Tôi muốn một cân sủi cảo.\nPhục vụ: Vâng ạ. Một cân sủi cảo có 40 cái.\nLưu Minh: 40 cái nhiều quá, cho tôi nửa cân thôi.\nPhục vụ: Nửa cân là 20 cái ạ. Ông muốn uống gì?\nLưu Minh: Cho tôi một cốc trà nhé.","audio_dialogue": "13-5.mp3","audio_vocab": "13-6.mp3"}]},{"id": 14,"title_cn": "我看了一个电影","title_pinyin": "Wǒ kànle yí gè diànyǐng","title_vn": "Tôi đã xem một bộ phim","goals": ["Có thể nghe hiểu và sử dụng trợ từ động thái \"了(2)\" để diễn đạt hành động đã xảy ra hoặc đã hoàn thành.","Nắm vững cách dùng phó từ phạm vi \"都\".","Nắm vững cách dùng cơ bản của một số từ ly hợp.","Hiểu và có thể miêu tả tình hình học tập."],"vocab": [{"hanzi": "上","pinyin": "shàng","pos": "dgt.","vn": "lên (xe), lên (tàu)"},{"hanzi": "火车","pinyin": "huǒchē","pos": "dt.","vn": "tàu hỏa"},{"hanzi": "中午","pinyin": "zhōngwǔ","pos": "dt.","vn": "buổi trưa"},{"hanzi": "开","pinyin": "kāi","pos": "dgt.","vn": "khởi hành, chạy (xe)"},{"hanzi": "有些","pinyin": "yǒuxiē","pos": "đt.","vn": "một số, có người"},{"hanzi": "有的","pinyin": "yǒude","pos": "đt.","vn": "có người, có cái"},{"hanzi": "了","pinyin": "le","pos": "trợ.","vn": "rồi (trợ từ hoàn thành)"},{"hanzi": "写","pinyin": "xiě","pos": "dgt.","vn": "viết"},{"hanzi": "都","pinyin": "dōu","pos": "phó.","vn": "đều"},{"hanzi": "听见","pinyin": "tīngjiàn","pos": "dgt.","vn": "nghe thấy"},{"hanzi": "不要","pinyin": "búyào","pos": "phó.","vn": "đừng, không nên"},{"hanzi": "说话","pinyin": "shuōhuà","pos": "dgt.","vn": "nói chuyện"},{"hanzi": "听","pinyin": "tīng","pos": "dgt.","vn": "nghe"},{"hanzi": "哪些","pinyin": "nǎxiē","pos": "đt.","vn": "những...nào"},{"hanzi": "字","pinyin": "zì","pos": "dt.","vn": "chữ"},{"hanzi": "汉语","pinyin": "Hànyǔ","pos": "danh từ riêng","vn": "tiếng Hán"},{"hanzi": "汉字","pinyin": "Hànzì","pos": "danh từ riêng","vn": "chữ Hán"},{"hanzi": "明年","pinyin": "míngnián","pos": "dt.","vn": "năm sau"},{"hanzi": "上","pinyin": "shàng","pos": "dgt.","vn": "bắt đầu (một việc gì đó đúng giờ)"},{"hanzi": "中学","pinyin": "zhōngxué","pos": "dt.","vn": "trường trung học"},{"hanzi": "小学","pinyin": "xiǎoxué","pos": "dt.","vn": "trường tiểu học"},{"hanzi": "中学生","pinyin": "zhōngxuéshēng","pos": "dt.","vn": "học sinh trung học"},{"hanzi": "小学生","pinyin": "xiǎoxuéshēng","pos": "dt.","vn": "học sinh tiểu học"},{"hanzi": "上学","pinyin": "shàngxué","pos": "dgt.","vn": "đi học"},{"hanzi": "他们","pinyin": "tāmen","pos": "đt.","vn": "họ, bọn họ"},{"hanzi": "她们","pinyin": "tāmen","pos": "đt.","vn": "họ (chỉ nữ giới)"},{"hanzi": "它们","pinyin": "tāmen","pos": "đt.","vn": "chúng nó"},{"hanzi": "晚","pinyin": "wǎn","pos": "tt.","vn": "muộn"}],"grammar": [{"title": "动态助词“了（2）”","explanation_vn": "Trợ từ động thái \"了(2)\" đặt sau động từ, biểu thị hành động đã xảy ra hoặc đã hoàn thành. Khi phủ định, dùng \"没\" và bỏ \"了\".","examples": [{"cn": "我看了一个电影。","pinyin": "Wǒ kànle yí gè diànyǐng.","vn": "Tôi đã xem một bộ phim."},{"cn": "我买了一个新电脑。","pinyin": "Wǒ mǎile yí gè xīn diànnǎo.","vn": "Tôi đã mua một chiếc máy tính mới."},{"cn": "我昨天没去商店买东西。","pinyin": "Wǒ zuótiān méi qù shāngdiàn mǎi dōngxi.","vn": "Hôm qua tôi không đi cửa hàng mua đồ."}]},{"title": "离合词（1）","explanation_vn": "Các từ như \"上课、下课、上班、下班、说话、读书、睡觉、看病、生病\" trong quyển này thuộc một loại kết cấu động từ đặc biệt, có thể tách hoặc ghép: khi ghép lại thì là một từ, khi chèn thêm thành phần khác vào giữa thì trở thành cụm từ. Vì vậy chúng được gọi là từ ly hợp. Khi tách ra, thành phần có thể chèn vào bị hạn chế.","examples": [{"cn": "睡觉 → 睡了觉；睡了一觉","pinyin": "Shuìjiào → Shuìle jiào; shuìle yí jiào","vn": "ngủ → đã ngủ; đã ngủ một giấc"},{"cn": "上课 → 上了课；上中文课","pinyin": "Shàngkè → Shàngle kè; shàng Zhōngwén kè","vn": "lên lớp → đã lên lớp; học tiết tiếng Trung"},{"cn": "说话 → 说了话；说了很多话","pinyin": "Shuōhuà → Shuōle huà; shuōle hěn duō huà","vn": "nói chuyện → đã nói chuyện; đã nói rất nhiều"}]},{"title": "范围副词“都”","explanation_vn": "Phó từ phạm vi \"都\" biểu thị toàn bộ, tổng quát; đối tượng được tổng quát đặt trước \"都\". Khi phủ định, từ phủ định đặt sau \"都\".","examples": [{"cn": "我们都会写了。","pinyin": "Wǒmen dōu huì xiě le.","vn": "Chúng tôi đều biết viết rồi."},{"cn": "我和我的朋友们都去。","pinyin": "Wǒ hé wǒ de péngyoumen dōu qù.","vn": "Tôi và các bạn tôi đều đi."},{"cn": "同学们都没听见。","pinyin": "Tóngxuémen dōu méi tīngjiàn.","vn": "Các bạn học sinh đều không nghe thấy."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "白家月","cn": "你们上火车后看见王老师了吗？","pinyin": "Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?"},{"speaker": "陈天中","cn": "没看见。中午车开后，有些人在看书，有些人睡觉了。","pinyin": "Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le."},{"speaker": "白家月","cn": "你呢？","pinyin": "Nǐ ne?"},{"speaker": "陈天中","cn": "我看了一个电影。","pinyin": "Wǒ kànle yí gè diànyǐng."}],"translation_vn": "Bạch Gia Nguyệt: Sau khi lên tàu các bạn có nhìn thấy cô Vương không?\nTrần Thiên Trung: Không thấy. Sau khi tàu chạy vào buổi trưa, có người đọc sách, có người ngủ.\nBạch Gia Nguyệt: Còn bạn thì sao?\nTrần Thiên Trung: Mình đã xem một bộ phim.","audio_dialogue": "14-1.mp3","audio_vocab": "14-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一飞","cn": "你们会说汉语了，也会写汉字了吗？","pinyin": "Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?"},{"speaker": "白家月","cn": "我们都会写了。","pinyin": "Wǒmen dōu huì xiě le."},{"speaker": "陈天中","cn": "老师，我听不见。","pinyin": "Lǎoshī, wǒ tīng bú jiàn."},{"speaker": "王一飞","cn": "请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","pinyin": "Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?"},{"speaker": "陈天中","cn": "我会写这些字了，您看！","pinyin": "Wǒ huì xiě zhèxiē zì le, nín kàn!"}],"translation_vn": "Vương Nhất Phi: Các em đã biết nói tiếng Hán rồi, cũng biết viết chữ Hán rồi chứ?\nBạch Gia Nguyệt: Chúng em đều biết viết rồi ạ.\nTrần Thiên Trung: Thưa cô, em không nghe rõ ạ.\nVương Nhất Phi: Mời cả lớp đừng nói chuyện! Hãy nghe câu hỏi của cô: Các em biết viết những chữ Hán nào rồi?\nTrần Thiên Trung: Em biết viết những chữ này rồi, cô xem này!","audio_dialogue": "14-3.mp3","audio_vocab": "14-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "刘明","cn": "明年女儿上中学。","pinyin": "Míngnián nǚ'ér shàng zhōngxué."},{"speaker": "王一雪","cn": "对。儿子也上小学了。","pinyin": "Duì. Érzi yě shàng xiǎoxué le."},{"speaker": "刘明","cn": "我们家有了一个中学生。","pinyin": "Wǒmen jiā yǒule yí gè zhōngxuéshēng."},{"speaker": "王一雪","cn": "还有了一个小学生。","pinyin": "Hái yǒule yí gè xiǎoxuéshēng."},{"speaker": "刘明","cn": "上学后，他们都忙了。","pinyin": "Shàngxué hòu, tāmen dōu máng le."},{"speaker": "王一雪","cn": "是的。太晚了，睡觉吧。","pinyin": "Shì de. Tài wǎn le, shuìjiào ba."}],"translation_vn": "Lưu Minh: Năm sau con gái sẽ lên trung học.\nVương Nhất Tuyết: Đúng vậy. Con trai cũng sẽ vào tiểu học rồi.\nLưu Minh: Nhà mình sắp có một học sinh trung học rồi.\nVương Nhất Tuyết: Còn có thêm một học sinh tiểu học nữa.\nLưu Minh: Sau khi đi học, cả hai đứa đều sẽ bận rộn.\nVương Nhất Tuyết: Đúng vậy. Muộn rồi, đi ngủ thôi.","audio_dialogue": "14-5.mp3","audio_vocab": "14-6.mp3"}]},{"id": 15,"title_cn": "大兴机场见！","title_pinyin": "Dàxīng Jīchǎng jiàn!","title_vn": "Hẹn gặp ở sân bay Đại Hưng!","goals": ["Có thể nghe hiểu và sử dụng các từ ngữ liên quan để diễn đạt ý định, kế hoạch đi du lịch.","Nắm vững câu phức liên hợp \"……, 还/也……\".","Hiểu văn hóa bàn ăn và lễ nghi đãi khách của Trung Quốc.","Hiểu về thủ đô của Trung Quốc — Bắc Kinh."],"vocab": [{"hanzi": "爱","pinyin": "ài","pos": "dgt.","vn": "yêu thích, thích"},{"hanzi": "哪个","pinyin": "nǎge","pos": "đt.","vn": "cái nào"},{"hanzi": "去年","pinyin": "qùnián","pos": "dt.","vn": "năm ngoái"},{"hanzi": "男朋友","pinyin": "nánpéngyou","pos": "dt.","vn": "bạn trai"},{"hanzi": "几","pinyin": "jǐ","pos": "số.","vn": "vài, mấy"},{"hanzi": "年","pinyin": "nián","pos": "dt.","vn": "năm"},{"hanzi": "好玩儿","pinyin": "hǎowánr","pos": "tt.","vn": "thú vị, hay"},{"hanzi": "西安","pinyin": "Xī'ān","pos": "danh từ riêng","vn": "Tây An"},{"hanzi": "北京","pinyin": "Běijīng","pos": "danh từ riêng","vn": "Bắc Kinh"},{"hanzi": "飞机","pinyin": "fēijī","pos": "dt.","vn": "máy bay"},{"hanzi": "要","pinyin": "yào","pos": "dgt.","vn": "cần, mất (thời gian)"},{"hanzi": "小时","pinyin": "xiǎoshí","pos": "dt.","vn": "giờ, tiếng đồng hồ"},{"hanzi": "家人","pinyin": "jiārén","pos": "dt.","vn": "người nhà"},{"hanzi": "时间","pinyin": "shíjiān","pos": "dt.","vn": "thời gian"},{"hanzi": "机场","pinyin": "jīchǎng","pos": "dt.","vn": "sân bay"},{"hanzi": "接","pinyin": "jiē","pos": "dgt.","vn": "đón"},{"hanzi": "住","pinyin": "zhù","pos": "dgt.","vn": "ở, sống, lưu trú"},{"hanzi": "早","pinyin": "zǎo","pos": "tt.","vn": "sớm"},{"hanzi": "那","pinyin": "nà","pos": "liên.","vn": "vậy thì, thế thì"},{"hanzi": "大兴机场","pinyin": "Dàxīng Jīchǎng","pos": "danh từ riêng","vn": "sân bay Đại Hưng"}],"grammar": [{"title": "并列复句“……，还/也……”","explanation_vn": "Câu phức liên hợp do hai hoặc nhiều mệnh đề có quan hệ lô-gic và kết cấu đối xứng tạo thành. Trong quyển này, chúng ta học câu phức liên hợp \"……, 还/也……\".","examples": [{"cn": "我喜欢这个，也喜欢那个。","pinyin": "Wǒ xǐhuan zhège, yě xǐhuan nàge.","vn": "Tôi thích cái này, cũng thích cái kia."},{"cn": "王老师是北京人，李文也是北京人。","pinyin": "Wáng lǎoshī shì Běijīng rén, Lǐ Wén yě shì Běijīng rén.","vn": "Cô Vương là người Bắc Kinh, Lý Văn cũng là người Bắc Kinh."},{"cn": "我喜欢喝中国茶，还喜欢吃中国菜。","pinyin": "Wǒ xǐhuan hē Zhōngguó chá, hái xǐhuan chī Zhōngguó cài.","vn": "Tôi thích uống trà Trung Quốc, còn thích ăn món Trung Quốc nữa."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "李文","cn": "你们爱吃哪个菜？","pinyin": "Nǐmen ài chī nǎge cài?"},{"speaker": "白家月","cn": "我喜欢这个，也喜欢那个。","pinyin": "Wǒ xǐhuan zhège, yě xǐhuan nàge."},{"speaker": "陈天中","cn": "这些菜都好吃，还很好看。","pinyin": "Zhèxiē cài dōu hǎochī, hái hěn hǎokàn."},{"speaker": "李文","cn": "我爱吃中国菜，也喜欢做。大家多吃点儿。","pinyin": "Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr."}],"translation_vn": "Lý Văn: Các bạn thích ăn món nào?\nBạch Gia Nguyệt: Mình thích món này, cũng thích món kia.\nTrần Thiên Trung: Mấy món này đều ngon, lại còn đẹp mắt nữa.\nLý Văn: Mình thích ăn món Trung Quốc, cũng thích nấu nữa. Mọi người ăn nhiều vào nhé.","audio_dialogue": "15-1.mp3","audio_vocab": "15-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "李文","cn": "你们都想去哪儿？","pinyin": "Nǐmen dōu xiǎng qù nǎr?"},{"speaker": "安妮","cn": "去年我和男朋友去了西安，今年我想去北京。","pinyin": "Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng."},{"speaker": "白家月","cn": "前几年我去了西安，非常好玩儿。今年我也想去北京。","pinyin": "Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng."},{"speaker": "李文","cn": "我和王老师都是北京人，北京非常漂亮。","pinyin": "Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang."}],"translation_vn": "Lý Văn: Mọi người đều muốn đi đâu vậy?\nAnnie: Năm ngoái mình và bạn trai đã đi Tây An, năm nay mình muốn đi Bắc Kinh.\nBạch Gia Nguyệt: Mấy năm trước mình đã đi Tây An, rất thú vị. Năm nay mình cũng muốn đi Bắc Kinh.\nLý Văn: Mình và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp.","audio_dialogue": "15-3.mp3","audio_vocab": "15-4.mp3"},{"label": "Bài khóa 3","type": "dialogue","lines": [{"speaker": "王一飞","cn": "你们的飞机到北京要几个小时？","pinyin": "Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?"},{"speaker": "白家月","cn": "九个小时。","pinyin": "Jiǔ gè xiǎoshí."},{"speaker": "王一飞","cn": "我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","pinyin": "Wǒ jiārén dōu zài Běijīng, xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā."},{"speaker": "安妮","cn": "我们星期日早上八点到大兴机场，早不早？","pinyin": "Wǒmen xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?"},{"speaker": "王一飞","cn": "不早。","pinyin": "Bù zǎo."},{"speaker": "白家月","cn": "谢谢老师！那我们和您姐姐在大兴机场见！","pinyin": "Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!"}],"translation_vn": "Vương Nhất Phi: Máy bay của các em đến Bắc Kinh mất mấy tiếng?\nBạch Gia Nguyệt: Chín tiếng ạ.\nVương Nhất Phi: Người nhà cô đều ở Bắc Kinh, chủ nhật chị gái cô cũng rảnh, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô.\nAnnie: Chúng em đến sân bay Đại Hưng lúc tám giờ sáng chủ nhật, có sớm quá không ạ?\nVương Nhất Phi: Không sớm đâu.\nBạch Gia Nguyệt: Cảm ơn cô! Vậy chúng em sẽ gặp chị gái cô ở sân bay Đại Hưng nhé!","audio_dialogue": "15-5.mp3","audio_vocab": "15-6.mp3"}]}],"pos_table": [{"pos_cn": "名词","pos_vn": "Danh từ","abbr": "dt."},{"pos_cn": "动词","pos_vn": "Động từ","abbr": "dgt."},{"pos_cn": "形容词","pos_vn": "Tính từ","abbr": "tt."},{"pos_cn": "代词","pos_vn": "Đại từ","abbr": "đt."},{"pos_cn": "副词","pos_vn": "Phó từ","abbr": "phó."},{"pos_cn": "介词","pos_vn": "Giới từ","abbr": "giới."},{"pos_cn": "连词","pos_vn": "Liên từ","abbr": "liên."},{"pos_cn": "助词","pos_vn": "Trợ từ","abbr": "trợ."},{"pos_cn": "数词","pos_vn": "Từ chỉ số đếm","abbr": "số."},{"pos_cn": "量词","pos_vn": "Lượng từ","abbr": "lượng."},{"pos_cn": "数量词","pos_vn": "Từ chỉ số lượng","abbr": "sl."},{"pos_cn": "叹词","pos_vn": "Từ cảm thán","abbr": "ct."},{"pos_cn": "拟声词","pos_vn": "Từ tượng thanh","abbr": "tượng."},{"pos_cn": "能愿动词","pos_vn": "Động từ năng nguyện","abbr": "đtnn."},{"pos_cn": "前缀","pos_vn": "Tiền tố","abbr": "ttố."},{"pos_cn": "后缀","pos_vn": "Hậu tố","abbr": "htố."}]};
